  Skill_117317_AwakerSkillBackgroundStory = {
    Text = "\"Pollux, senin kutsal kalbin Işık Taşıyıcı'nın kendi parlaklığını barındırıyor. Bu şanı, O'na duyduğun saygı gibi koru.\"\nVe böylece, yalanların tacını başına yerleştirdi, asla gevşemeye cesaret edemedi.\n\"Pollux, korkma. Git ve benim için özgürlüğün nasıl bir şey olduğunu tat...\"\nAma bu şan sayesinde her şeyi kazandı ve onun yüzünden her şeyi kaybetti. Sonunda tacın gerçek yüzünü gördü: görünmez zincirler.\nBöylece tacı parçaladı. İlk kez, boş kalbi gün ışığı kadar parlak bir ışıkla parladı—ama o öfkeli ağıtlar artık diğer yarısının kulaklarına ulaşamıyordu."
  },
  Skill_117317_Desc = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver. Bu turdaki bir sonraki Pollux Komut Kartı “Izdırapla Kefaret” kazanır. Eline 1 adet <DerivativeCardKeywords_118:\"Sacred Heart\"> koy."
  },
  Skill_117317_EffectNameList = {Text = "Hasar"},
  Skill_117317_Name = {
    Text = "Günahsız Kutsal Hüküm"
  },
  Skill_117317_OverLimitUtlSkillDesc = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver, bu turdaki bir sonraki Komut Kartının “Izdırapla Kefaret” etkisinden yararlanmasını sağla. Eline 2 adet <DerivativeCardKeywords_118:\"Sacred Heart\"> koy. Bu tur, Pollux’un her Komut Kartı fazladan %50 “Izdırapla Kefaret” etkisi kazanır ve bir sonraki Komut Kartın 1 kez ek olarak etki eder."
  },
  Skill_117317_PropertyNameList = {
    Text = "Saldırı*GrowValue1"
  },
  Skill_117318_AwakerSkillBackgroundStory = {
    Text = "Geçmişte, gözleri karanlıkla örtülüydü ve bu yüzden o karanlığı gün ışığı sandı. Ama gerçeği gördüğünde, dönüp ters yöne yürüdü. Çünkü artık anlıyor: hangi yöne giderse gitsin, adımları her zaman ışık tarafından yönlendirilmişti."
  },
  Skill_117318_Desc_0 = {
    Text = "Pollux <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Oynandığında ve Atma Aşamasından sonra, 3 yığın <ZuiyinKeywords:Günah İşareti> kazan; eldeki her kart için 1 ek yığın <ZuiyinKeywords:Günah İşareti> kazan."
  },
  Skill_117318_Desc_15 = {
    Text = "Pollux <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Oynandığında ve atma aşamasından sonra 3 yığın <ZuiyinKeywords:Günah İşareti> kazan, artı eldeki her kart için 1 ek yığın. \"Kutsal Kalp\" Hasarın %100'üne eşit Kanama uygular. Bir kart oynayarak Çekme Destesi'ne karıştırıldıktan sonra, o \"Kutsal Kalp\"in Arithmetica Maliyeti bu turda 0 olur ve Hasarın %100'üne eşit <BleedingIconKeywords:Kanama> uygular."
  },
