  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "O kibirlidir, içindeki onarılamaz boşluğu gururla maskeler. Bir zamanlar kim olduğunu unutmuştur ve kim olması gerektiğini de unutmuştur. Sayısız takipçi ayaklarının dibinde eğilir, ancak saygılarının yankılarında en hayati gerçeği unutur: bu solgun kadere çoktan boyun eğmiştir."
  },
  Skill_119763_BattleDesc = {
    Text = "2 Arithmetica kazan ve 2 kart çek. Bir sonraki turun başında [Arg3] <SacrificeKeyWord:Kurban> çek. <RippleKeywords:Aftershock>: [Arg4] <SacrificeKeyWord:Kurban> kaldır."
  },
  Skill_119763_Desc = {
    Text = "2 Arithmetica kazan ve 2 kart çek. Bir sonraki turun başında Maksimum Canının [Arg1]%’i kadar <SacrificeKeyWord:Kurban> çek. <RippleKeywords:Artçı Sarsıntı>: Maksimum Canının [Float:Arg2]%’i kadar “Kurban” yığınını kaldır."
  },
  Skill_119763_EffectNameList = {
