  Skill_119765_AwakerSkillBackgroundStory = {
    Text = "O hafifmeşreptir, parçalanmış gerçekliğe karşı savaşmak için şenliği kullanır. \"Haydi dans edelim,\" diye buyurdu, \"Tanrı'ya adanmış bir dans. Bize sapkın nedensellik, kaotik bir geçmiş ve ele avuca sığmaz bir gelecek bahşettiği için O'na şükredelim.\" Spot ışığı altında, tüm varoluşun tek odak noktası odur."
  },
  Skill_119765_BattleDesc = {
    Text = "<Posse:[Arg7]> Keyflare kazan. Mevcut Dokunaç Duruşuna göre farklı etkiler tetikle:\n \"Yükselen Dalgalar\": <TentacleInjurieIconKeywords:Dokunaç Hasarı> +[TentaclePower:Arg1], 1 Dokunaç üret.\n \"Sakin Deniz\": <Block:[Block:Arg2]> Kalkan kazan, Kalkanın %50’sini bir sonraki tura taşı.\n \"Azgın Dalgalar\": En yüksek Can’a sahip düşmana, [Arg5]% Dokunaç Hasarı bonusuyla, [Arg3] kez <Damage:[Damage:Arg4]> Hasar ver."
  },
  Skill_119765_Desc = {
    Text = "Keyflare Yenilenmesinin [Arg6]%’üne eşit Keyflare kazan. Mevcut Dokunaç Duruşuna göre farklı etkiler tetikle:\n \"Yükselen Dalgalar\": <TentacleInjurieIconKeywords:Dokunaç Hasarı> +[TentaclePower:Arg8], 1 Dokunaç üret.\n \"Sakin Deniz\": <Block:[Block:Arg9]> Kalkan kazan, Kalkanın %50’sini bir sonraki tura taşı.\n \"Azgın Dalgalar\": En yüksek Can’a sahip düşmana, [Arg5]% Dokunaç Hasarı bonusuyla, [Arg3] kez <Damage:[Damage:Arg4]> Hasar ver."
