  Skill_122485_AwakerSkillBackgroundStory = {
    Text = "Geçmişi unutma, A.U.G.E.'yi unutma.\nUnutmak, ihanet etmektir.\nVe Mouchette asla ihanet etmeyecek."
  },
  Skill_122485_Desc_0 = {
    Text = "Mouchette <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Dramatik Karşılaşma\" Hasar vuruşları +2. \"Dramatik Karşılaşma\" her tetiklendiğinde, Mouchette'in \"Vuruş\" Geçici Final Hasar +%25. Hemen 1 Geçici \"Ölümcül Patlama\" oluştur."
