  },
  Skill_125371_AwakerSkillBackgroundStory = {
    Text = "Kökeninden asla bahsetmezler; yalnızca doğuşunu müjdeleyen Tarifsiz Vectten söz ederler.\nBilincin vectte erir; geçmişin vectte erir; kafatasın vectte erir... beynin bile coşkuya dönüşür.\nAğızda eriyen bir lezzet—\"Özlem\" katalizör olarak."
  },
  Skill_125371_BattleDesc_0 = {
    Text = "Tüm düşmanlara garantili Kritik Vuruş olarak <Damage:[Damage:Arg1]> Hasar ver ve [Arg2]% Zehir uygula. <ResonanceKeywords:Rezonans 3>: <EmbryoFusionIconKeywords:Embriyo Füzyonu> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_BattleDesc_1 = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> garantili Kritik Vuruş Hasarı ver ve [Arg2]% Zehir uygula, <EmbryoFusionIconKeywords:Embriyo Füzyonu>+ [Arg6]. <ResonanceKeywords:Rezonans 3>: <EmbryoFusionIconKeywords:Embriyo Füzyonu> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_Desc_0 = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> garantili Kritik Vuruş Hasarı ver ve [Arg2]% Zehir uygula. <ResonanceKeywords:Rezonans 3>: <EmbryoFusionIconKeywords:Embriyo Füzyonu> +[Arg4]."
  },
  Skill_125371_Desc_1 = {
