  Skill_125372_Desc_1 = {
    Text = "Hedefe ve <HPAndShieldMax:en yüksek Can ve Kalkan>'a sahip düşmana <Damage:[Damage:Arg1]> Hasar ver, 1 yığın <PVPLostSoulKeyWords:Büyülenmiş> uygula."
  },
  Skill_125372_Name_1 = {
    Text = "Kesmeyen İpek"
  },
  Skill_125373_AwakerSkillBackgroundStory = {
    Text = "Neden ayartsın ki? Zaten karşı koyacak güçleri yoktu.\nNeden kışkırtsın ki? Güç ve arzunun girdabı—gittikçe yükselen, gittikçe genişleyen—görünen her şeyi yutana dek durmayacak.\nÇünkü yalnızca \"Aşk\" ile tutsak edilmiş bir sıradan insanın iliği yutulması pek de mümkün değildir. Çünkü \"Hırs\" ile marine edilmemiş sıradan bir ceset tamamen tatsızdır.\nRüyasız Diyar, avcının avına fırlattığı bir kırıntı ödülden ibarettir.\nO Vecdin kalbinde hiçbir şey yoktur—yalnızca sonsuz Kaos, sınırsız ve tuhaf bir fantazmagori."
  },
  Skill_125373_Desc_0 = {
    Text = "Xu <Energy:[Energy:Arg1]> puan Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Xu'nun her Komut Kartı türü, tur başına ilk kez <ResonanceKeywords:Rezonans> efektini tetiklediğinde temel Arithmetica Maliyeti 0 olur."
  },
  Skill_125373_Desc_15 = {
    Text = "Xu <Energy:[Energy:Arg1]> puan Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Xu'nun her Komut Kartı türü, tur başına ilk kez <ResonanceKeywords:Rezonans> efektini tetiklediğinde temel Arithmetica Maliyeti 0 olur. <WitherKeywords0:Büyülenmiş>'in yığılma üst sınırı 15 katmana yükselir, Xu'nun her tur ilk oynadığı Komut Kartı 1 ek kez etki eder."
  },
  Skill_125373_EffectNameList = {Text = "Aliemus"},
