  Skill_125376_AwakerSkillBackgroundStory = {
    Text = "Çağlar boyunca, \"Aşk\" kelimesi bir siren şarkısından başka bir şey olmamıştır; ruhları, geri dönmeyi reddettikleri bir günah denizine çağıran bir ezgi."
  },
  Skill_125376_Desc_0 = {
    Text = "[<DevouredIconKeywords:Yutma>: Tüm düşmanların <ExhaustionIconKeywords:GÜÇ> değerini geçici olarak [Exhaustion:Arg1] azalt.] [Arg2] Arithmetica kazan ve tüm düşmanlara [Poison:Arg3] yığın <IntoxicationIconKeywords:Zehir> uygula. Seç: <WitherKeywords1:Nişanla> veya <WitherKeywords2:Büyüle>."
  },
  Skill_125376_Desc_3 = {
    Text = "[[<DevouredIconKeywords:Yutma>: Tüm düşmanların [Exhaustion:Arg1] puan <ExhaustionIconKeywords:Gücünü> geçici olarak azaltır.] [Arg2] puan Arithmetica kazan, tüm düşmanlara [Poison:Arg3] kat <IntoxicationIconKeywords:Zehir> uygula. Kendi bir sonraki tetiklenen <ResonanceKeywords:Rezonans> etkisi iki katına çıkar. Seç: <WitherKeywords1:Nişanlama> veya <WitherKeywords2:Büyüleme>."
  },
