  Skill_126490_BattleDesc_0 = {
    Text = "Arachne <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Yok Oluş\" şu şekilde değiştirilir: Ultra Alanından 1 Komut Kartı seç, onu çıkar ve bir sonraki oynanışında iki kez tetiklenmesini sağla ve oynanan bir sonraki Komut Kartının <SingularityKeywords3:Tekillik Mekiği> tetiklemesini sağla."
  },
  Skill_126490_BattleDesc_15 = {
    Text = "Arachne <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Yok Oluş\" şu şekilde değişir: \"Ultra Uzay'dan seçilen bir Komut Kartını ele çek; oynandığında +1 kez tetiklenir. Her düşman için, onlara <CutKeywords:Son Karar> değerlerinin %50'si kadar <RealDamage:Sabit Hasar> ver. Arachne'nin bir sonraki Taşkınlığından kazanılan Kalkan ve Hasar Güçlendirmesi +%50. Oynanan bir sonraki Komut Kartı <SingularityKeywords3:Boyut Mekiği> tetikler.\""
  },
  Skill_126490_Desc_0 = {
    Text = "Arachne [Arg2]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Yok Oluş\" şu şekilde değiştirilir: Ultra Uzay'dan 1 Komut Kartı seç, onu çıkar ve bir sonraki oynanışında iki kez tetiklenmesini sağla, ayrıca bir sonraki oynanan Komut Kartının <SingularityKeywords3:Boyut Mekiği>'ni tetiklemesini sağla."
  },
  Skill_126490_Desc_15 = {
    Text = "Arachne, Temel Aliemus'unun [Arg2]%'si kadar Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Yok Oluş\" şu şekilde değişir: \"Ultra Uzay'dan seçilen bir Komut Kartını ele çek; oynandığında +1 kez tetiklenir. Her düşman için, onlara <RealDamage:Son Karar> değerlerinin %50'si kadar <CutKeywords:Sabit Hasar> ver. Arachne'nin bir sonraki Taşkınlığından kazanılan Kalkan ve Hasar Güçlendirmesi +%50. Oynanan bir sonraki Komut Kartı <SingularityKeywords3:Boyut Mekiği> tetikler.\""
