  Skill_130476_Name = {
    Text = "Kaderin Ağıtı"
  },
  Skill_130477_Desc = {
    Text = "Bu niyete geçildiğinde, \"Kader Bağlayıcı\" ve <Chapter5_Monster_Fervor4:Coşku>'yu kaldır ve diğer müttefikleri temizle. Kendi Maksimum can'ını %250 artır, toplam Kadim Közleri iki katına çıkar ve 5 yuvalı bir \"Boyutsal Yarık\" aç."
