  Skill_130513_Desc_1 = {
    Text = "<PVPWeaponKeywords:Kader Çarkı>: Kuşanıldığında ve tur başında, aşağıdaki etkilerden birini rastgele tetikler: <Energy:[Energy:Arg1]> Aliemus kazanır ve kendisine <PVPSlowKeywords:Durgunluk> uygular; <Energy:[Energy:Arg3]> Aliemus kazanır; <Energy:[Energy:Arg4]> ve [Arg5] adet <PVPDerivativeCardKeywords_17:\"İlham\"> kazanır."
  },
  Skill_130513_Name_1 = {
    Text = "Bilgeliğin Kazıkları"
  },
  Skill_130928_Desc_1 = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar verir. Öldürme gerçekleşmezse [Arg2] katman <PVPWaterPowerKeyWords:Girdap> kazanır."
  },
  Skill_130928_Name_1 = {
    Text = "Uçurumsal! Girdap! Mega-Patlama!"
  },
  Skill_130929_AwakerSkillBackgroundStory = {
    Text = "Savaş alanına sıçrar, korkunç bir top neşeyle yanında sallanır. Hiçbir endişe ya da tehlike ağırlık taşımaz, çünkü dostluk bağıyla kıyaslandığında geri kalan her şey önemsizdir. Arkadaşlar tehlikede! Vortice sahneye çıkıyor!"
  },
  Skill_130929_BattleDesc_0 = {
    Text = "Vortice <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: 1 \"Doldur!\" çek. Vortice bir Av kullandıktan sonra, Vortice'nin bir sonraki Taşkınlığı ek %[Arg2] Dokunaç Hasarı Bonusu kazanır, en fazla [Arg3] kez yığılır."
  },
  Skill_130929_BattleDesc_15 = {
    Text = "Vortice <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: 1 \"Yeniden Doldur!\" çek. Vortice Av'ı serbest bıraktıktan sonra, bir sonraki Taşkınlığı ek [Arg2]% Dokunaç HSR Bonusu kazanır ve bir sonraki Taşkınlık, en yüksek Cana sahip düşmana Maksimum Canın [Arg4]%'si kadar <RealDamage:Sabit Hasar> verir; en fazla [Arg3] <plural value=\"[Arg3]\" singular=\"kez\" plural=\"kez\"> yığılır."
  },
  Skill_130929_Desc_0 = {
    Text = "Vortice [Arg5]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: 1 \"Yeniden Doldur!\" çek. Vortice bir Av Serbest Bıraktıktan sonra, bir sonraki Vortice Aliemus Taşkınlık ek olarak [Arg2]% Dokunaç HSR Bonusu kazanır, en fazla [Arg3] kez yığılır."
  },
  Skill_130929_Desc_15 = {
    Text = "Vortice, Temel Aliemus'unun [Arg5]%'si kadar Aliemus kazanır. <ExaltIconKeywords:Uyanış>: 1 \"Yeniden Doldur!\" çek. Vortice Av'ı serbest bıraktıktan sonra, bir sonraki Taşkınlığı ek [Arg2]% Dokunaç HSR Bonusu kazanır ve bir sonraki Taşkınlık, en yüksek Cana sahip düşmana Maksimum Canın [Arg4]%'si kadar <RealDamage:Sabit Hasar> verir; en fazla [Arg3] <plural value=\"[Arg3]\" singular=\"kez\" plural=\"kez\"> yığılır."
  },
  Skill_130929_EffectNameList = {
    Text = "Aliemus,Dokunaç DMG Bonusu"
  },
  Skill_130929_Name = {
    Text = "İŞTE GELİYOR!"
  },
  Skill_130929_PropertyNameList = {
    Text = "$GrowValue1,$GrowValue2%"
  },
  Skill_130930_Desc_1 = {
    Text = "<PVPWeaponKeywords:Wheel of Destiny>: \"Taşkınlık\" tan sonra, kendine <Block:[Block:Arg1]> Karakter Kalkanı ve <DelayKeywords:Gecikme>: <Energy:[Energy:Arg2]> Aliemus bahşet."
  },
  Skill_130930_Name_1 = {
    Text = "Uzak Cennet"
  },
  Skill_130931_AwakerSkillBackgroundStory = {
    Text = "Girdap yıkım getirir; Uçurum unutuşu. Bir zamanlar güneş ışığına ve dostluğa özlem duyan bir kız, sonunda sonsuz yalnızlığa geri atıldı. Çığlıklar, feryatlar, bozulma ve çöküş—Moskstraumen'deki zamanını sonsuz bir döngü tanımladı. Bu, dalgaların altındaki açlığın kükremesidir, her şeyi yutan. Ve Vortice'nin onu fethettiğinin kanıtıdır."
  },
  Skill_130931_BattleDesc_0 = {
    Text = "Eldeki tüm kartlardaki <BurningKeywords:Yanma> etkisini kaldır. Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver; en yüksek HP'ye sahip düşmana 2x Hasar ver. En fazla 3 ek Kalıcı Dokunaç([Arg4]) Kurban et; her biri bu Yücelişin Krit. Hasarını +50% artırır.(Mevcut Krit. Oranı: [Arg5]%. Dokunaç Hasarı Bonusu: [Arg8]%)."
  },
  Skill_130931_BattleDesc_1 = {
    Text = "Eldeki tüm kartlardan <BurningKeywords:Yanma> etkisini kaldır. Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver, en yüksek Can değerine sahip düşmana 2x Hasar uygula. En fazla 3 ek Kalıcı Dokunaç([Arg4]) Kurban et; her biri bu Yücelişin Krit. Hasarını +%50 artırır.(Mevcut Krit. Oranı: [Arg5]%. Dokunaç Hasar Bonusu: [Arg8]%). [Arg6] Diyar Ustalığı kazan."
  },
  Skill_130931_BattleDesc_3 = {
    Text = "Eldeki tüm kartların <BurningKeywords:Yanma> durumunu dağıt. Tüm düşmanlara <Damage:[Damage:Arg1]> puan Hasar verir, en yüksek canlı düşmana üç kat Hasar verir. En fazla 3 adet ekstra Kalıcı Dokunaç ([Arg4] adet) feda et, her biri bu Taşkınlık'ın Kritik Hasarını +%50 artırır (Mevcut Kritik Oranı: [Arg5]%. Dokunaç Hasarı Bonusu: [Arg8]%). [Arg6] puan Diyar Ustalığı kazanır, her 20 Aliemus tüketildiğinde diğer Uyandırıcılar 1 Aliemus kazanır."
  },
  Skill_130931_Desc_0 = {
    Text = "Eldeki tüm Kartlardan <BurningKeywords2:Yanma> etkisini kaldır. Tüm düşmanlara, [Arg7]% <TentacleInjurieIconKeywords:Tentacle Hasarı> Bonusu kadar Hasar ver, en yüksek HP'ye sahip düşmana 2x Hasar uygula. En fazla 3 ek Kalıcı Dokunaç Kurban et; her biri bu Exalt'ın Krit. Hasarını +%50 artırır."
  },
  Skill_130931_Desc_1 = {
    Text = "Eldeki tüm dardlardaki <BurningKeywords2:Yanma> etkisini kaldır. Tüm düşmanlara, [Arg7]% <TentacleInjurieIconKeywords:Dokunaç Hasarı> Bonusu kadar Hasar ver; en yüksek HP'ye sahip düşmana 2x Hasar ver. En fazla 3 ek Kalıcı Dokunaç Kurban et; her biri bu Yücelişin Krit. Hasarını +50% artırır. [Arg6] Diyar Ustalığı kazan."
  },
  Skill_130931_Desc_3 = {
    Text = "Eldeki tüm Kartlardan <BurningKeywords2:Yanma> etkisini kaldır. Tüm düşmanlara, [Arg7]% <TentacleInjurieIconKeywords:Dokunaç Hasarı> Bonusu kadar Hasar ver; en yüksek Can değerine sahip düşmana 3 kat Hasar uygula. En fazla 3 ek Kalıcı Dokunaç Kurban et; her biri bu Yücelişin Krit. Hasarını +%50 artırır. [Arg6] Diyar Ustalığı kazan ve harcanan her 20 Aliemus için diğer Uyananlar 1 Aliemus kazansın.\n"
  },
