  Skill_131856_BattleDesc_0 = {
    Text = "Saya <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullanıldıktan sonra diğer konumlardaki \"<DestructionKeywords:İmha Et>\" özelliğine sahip olmayan Uyandırıcıların Komut Kartlarına <ErosionColorInkKeywords:Algı Bükülmesi> ekler. Her turda ilk 3 kez <ErosionColorInkKeywords:Algı Bükülmesi> içeren bir Komut Kartı oynanması, Saya ve o Komut Kartının ait olduğu Uyandırıcının <Energy:[Energy:Arg2]> Aliemus kazanmasını sağlar."
  },
  Skill_131856_BattleDesc_15 = {
    Text = "Saya <Energy:[Energy:Arg1]> puan Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullanıldıktan sonra Saya <Energy:[Energy:Arg4]> puan Aliemus ve 1 kat \"<KaiHuajishu:Gynoecium>\" kazanır. Farklı konumlardaki diğer Uyandırıcıların \"<DestructionKeywords:İmha Et>\" içermeyen Komut Kartlarına <ErosionColorInkKeywords:Algı Bükülmesi> ekler. Her tur ilk 3 kez <ErosionColorInkKeywords:Algı Bükülmesi> içeren bir Komut Kartı oynanması, Saya ve o Komut Kartının sahibi Uyandırıcının <Energy:[Energy:Arg2]> puan Aliemus kazanmasını sağlar."
  },
  Skill_131856_Desc_0 = {
    Text = "Saya [Arg3]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullanıldıktan sonra diğer Uyandırıcıların \"<DestructionKeywords:İmha Et>\" içermeyen Komut Kartlarına <ErosionColorInkKeywords:Algı Bükülmesi> ekler. Her turda <ErosionColorInkKeywords:Algı Bükülmesi> içeren ilk 3 Komut Kartı oynanıldığında Saya ve o Komut Kartının ait olduğu Uyandırıcı <Energy:[Energy:Arg2]> Aliemus kazanır."
  },
  Skill_131856_Desc_15 = {
    Text = "Saya [Arg3]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullanıldıktan sonra Saya <Energy:[Energy:Arg4]> Aliemus ve 1 katman \"<KaiHuajishu:Gynoecium>\" kazanır. Diğer Uyandırıcıların \"<DestructionKeywords:İmha Et>\" içermeyen Komut Kartlarına <ErosionColorInkKeywords:Algı Bükülmesi> ekler. Her turda <ErosionColorInkKeywords:Algı Bükülmesi> içeren ilk 3 Komut Kartı oynanıldığında Saya ve o Komut Kartının ait olduğu Uyandırıcı <Energy:[Energy:Arg2]> Aliemus kazanır."
  },
