  Skill_132357_Desc = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan ve sırasıyla kendine, oyuncuya ve ön sıradaki düşmana Durum ekle. Oynanan değer ve gerçek değer her biri 1 kez."
