  },
  Skill_132359_AwakerSkillBackgroundStory = {
    Text = "Işığın yedi rengi, göz kamaştırıcı ve büyüleyici~"
  },
  Skill_132359_Desc = {
    Text = "Oyuncu [Power:Arg1] puan <PowerIconKeywords:Güç>, <Block:[Block:Arg2]> puan kalkan, [Heal:Arg3] puan iyileştirme, [TentaclePower:Arg4] puan <TentacleInjurieIconKeywords:Dokunaç Hasarı>, [Counterattack:Arg5] katman <RetaliateIconKeywords:Karşı Saldırı> kazanır, ön sıra düşmanlara <Damage:[Damage:Arg6]> puan hasar verir [Arg7] kez, [Poison:Arg8] katman <IntoxicationIconKeywords:Zehirlenme> uygular, [Exhaustion:Arg9] katman <ExhaustionIconKeywords:Tükenme> uygular, [FateCut:Arg10] katman <CutKeywords:Kader Hükmü> uygular."
  },
  Skill_132359_Name = {
