  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "\nOkyanus derin ve sakindir; yaşam arzusunu ve ölüm korkusunu taşır.\nYine de, okyanusu kahkaha ve yaramazlıkla doldurmayı seçenler vardır—Aurita böyle bir davet uzattığında, insanın aklına hep “neden onunla biraz eğlenmeyeyim ki” düşüncesi gelir ve basit bir sevinç kalbi doldurur."
  },
  Skill_132429_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver. Çekme Destesi ve Atılmış Kart Destesi’nden en fazla 10 \"Bez Bölünmesi\" harca; her biri 1 ek Hasar örneği sağlar. Ele 2 \"Bez Bölünmesi\" al. Bu savaşta Aurita’nın Hasar çıktısını [Arg2] artır."
  },
  Skill_132429_Desc_2 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:Delici Hasar> ver. Çekme destesinden ve Atılmış Kart Deste­sinden en fazla 10 adet \"Bez Bölünmesi\" kartı tüket; her biri fazladan bir Hasar örneğine neden olur. Eline 2 adet \"Bez Bölünmesi\" kartı yerleştir. Bu savaşta Aurita’nın verdiği Hasarı [Arg2] puan artır."
  },
