  Skill_133365_AwakerSkillBackgroundStory = {
    Text = "İpliklerin kopuş sesini sayısız kez duymuştu.\nGerçekleşmemiş bir kavuşma. Söylenmemiş bir itiraf. Doğmamış bir çocuk.\nGün yüzü görmemiş bir melodi. Kazanılamamış bir savaş. Hayatta kalamamış bir medeniyet.\nİplikler örülür. İplikler kopar. İplikler o devasa ağa yeniden akar.\nKaderin tanrıları çoktan biliyordu, hiçbir şey gerçekten yok olmaz, hiçbir şey gerçekten var olmamıştır."
  },
  Skill_133365_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan. Diğer Uyandırıcılar <Energy:[Energy:Arg2]> Aliemus kazanır. Bir sonraki \"Ebedi Dokuma\" ek bir \"<DerivativeCardKeywords_138:Yönlendirici İplikler>\" oluşturur ve Çekme Destesi ile Atılmış Kart Destesine yerleştirir."
  },
