  Skill_142695_AwakerSkillBackgroundStory = {
    Text = "Tüm sevdiklerinin en canlı ve neşeli yanlarını sakladı, tüm düşmanlarına en acımasız ve uzun işkenceleri reva gördü.\nKadehlerin şakırdadığı her gecenin sonunda, gülerek boş bedenlerden oluşan bir Derin Deniz'e düştü."
  },
  Skill_142695_BattleDesc = {
