  Skill_142700_BattleDesc_0 = {
    Text = "Pontos <Energy:[Energy:Arg1]> puan Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Destede her 3 adet \"Gaunt\" bulunduğunda \"Amansız Av\" ekstra 1 kat <BattueKeywords:Sürü Avı> kazanır. Her Pontos kartı oynadığında bir sonraki \"Amansız Av\"ın geçici Güç azaltma etkisi [Arg3]% artar; her turda en fazla 3 kez tetiklenebilir."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Destede her 2 \"Gaunt\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> için \"Amansız Av\" 1 ekstra <BattueKeywords:Sürü Avı> yığını kazanır. Her 1 Pontos Kartı oynanışında, bir sonraki \"Amansız Av\"ın Geçici GÜÇ▼ etkisi +[Arg3]% artar; bu etki tur başına en fazla 3 kez tetiklenir. Her turda \"Vuruş\" ve \"Savunma\"nın 1. oynanışında +<Energy:[Energy:Arg4]> Aliemus kazan."
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos [Arg2]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Destede her 3 adet \"Gaunt\" bulunduğunda \"Amansız Av\" 1 kat <BattueKeywords:Sürü Avı> kazanır. Her Pontos kartı oynadığında bir sonraki \"Amansız Av\"ın geçici Güç azaltma etkisi [Arg3]% artar; her turda en fazla 3 kez tetiklenebilir."
