  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "İnsan kulağı ve mevcut Gümüş çip teknolojisi, şimdilik Pontos'un av ıslığından herhangi bir geçerli bilgi elde edememektedir.\nAncak Ebwynnos tarafından asimile edilen tüm bireyler, Islık'ın emirlerine uymayı son derece hızlı bir şekilde Adaptasyon etmiş görünmektedir."
  },
  Skill_142846_Desc = {
