  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Kader Çarkı>: Bir müttefik öldüğünde, <Energy:[Energy:Arg1]> Aliemus kazan. Bir müttefik Canlandığında, <Energy:[Energy:Arg2]> Aliemus kazanır. Aliemus kazanma etkisi yalnızca hedefin Aliemus'u dolu olmadığında geçerlidir, en fazla [Arg8] kez. Sayaç tükendiğinde, bu Kader Çarkı'nı İmha Et."
  },
  Skill_144438_Name_1 = {
    Text = "Ruh Senkronizasyonu"
  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "Peri ile büyücü, küçük bir kasabanın köşesindeki ıssız bir arazide karşılaştı.\nO, şık giyimli yabancı çocuklara gülümseyerek el sallıyordu; büyücü ise gözlerini annelerinin bileğindeki şıngırdayan altın bilezikten ayıramıyordu.\nBakışları havada kesişti ve bir anda her biri diğerinin niyetini anladı.\nBu sessiz çekişmede büyücü daha becerikli çıktı; yılların verdiği deneyimin gücüyle dar bir farkla galip geldi.\nVe böylece, yeni ve güzel bir dolandırıcılık ve kazıkçılık girişimi perdesini açtı."
  },
  Skill_144486_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Yutmak>: 1 yığın <WormGrowth1:Tokluk> kazan. HSR verirken hedefe [<Corrosion:Aşınma>:Arg10] yığın <Corrosion:Aşınma> uygula.] Eldeki tüm kartlardan <BurningKeywords2:Yanma>'yı gider. <Block:[Block:Arg2]> Kalkan kazan. Tüm düşmanlara [Arg8] kez <Damage:[Damage:Arg1]> HSR ver. Her <WormGrowth1:Tokluk> yığını, Taşkınlık Temel HSR'ını ve Kalkan Üretimini [Arg6]% artırır. Tüm <SacrificialMark1:Adak> yığınlarını tüket; her yığın Taşkınlık vuruş sayısını 1 artırır ve eşit sayıda <WormGrowth1:Tokluk> yığınına dönüşür. Mevcut <WormGrowth1:Tokluk> yığınları: [Arg9]. Bu savaşta kazanılan yığınlar: [Arg11]"
  },
  Skill_144486_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:Yutmak>: <WormGrowth2:Tokluk> kazan. HSR verirken hedefe [<Corrosion:Aşınma>:Arg10] yığın <Corrosion:Aşınma> uygula.] Eldeki tüm kartlardan <BurningKeywords2:Yanma>'yı gider. <Block:[Block:Arg2]> Kalkan kazan. Tüm düşmanlara [Arg8] kez <Damage:[Damage:Arg1]> HSR ver. Her <WormGrowth2:Tokluk> yığını, Taşkınlık Temel HSR'ını ve Kalkan Üretimini [Arg6]% artırır. Tüm <SacrificialMark1:Adak> yığınlarını tüket; her yığın Taşkınlık vuruş sayısını 1 artırır ve eşit sayıda <WormGrowth2:Tokluk> yığınına dönüşür. Mevcut <WormGrowth2:Tokluk> yığınları: [Arg9]. Bu savaşta kazanılan yığınlar: [Arg11]"
  },
  Skill_144486_Desc_0 = {
    Text = "[<DevouredIconKeywords:Yutmak>: 1 yığın <WormGrowth1:Tokluk> kazan. HSR verirken hedefe [<Corrosion:Aşınma>:Arg10] yığın <Corrosion:Aşınma> uygula.] Eldeki tüm kartlardan <BurningKeywords2:Yanma>'yı gider. <Block:[Block:Arg2]> Kalkan kazan. Tüm düşmanlara [Arg8] kez <Damage:[Damage:Arg1]> HSR ver. Her <WormGrowth1:Tokluk> yığını, Taşkınlık Temel HSR'ını ve Kalkan Üretimini [Arg6]% artırır. Tüm <SacrificialMark1:Adak> yığınlarını tüket; her yığın Taşkınlık vuruş sayısını 1 artırır ve eşit sayıda <WormGrowth1:Tokluk> yığınına dönüşür."
