  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "Açgözlülük, insan doğasının gerçek rengidir.\nHiç kimse şekerin cazibesine direnemez; Peri Vaftiz Annenin kendisi bile.\nCaraboo sırıttı; simsiyah, sivri dişlerini ortaya koydu."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullandıktan sonra, bir sonraki <DerivativeCardKeywords_160:\"Mucize Bereket\">'in maliyeti -3 Arithmetica azalır ve her <FaxianKeywords:Keşfet> seçeneği, 1 fazla <DerivativeCardKeywords_152:\"Bereket\"> kartı içeren bir sete yükseltilir. Çekme Destene karıştırmak için 1 set seç."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullandıktan sonra, bir sonraki <DerivativeCardKeywords_160:\"Mucize Bereket\">'in maliyeti -3 Arithmetica azalır ve her <FaxianKeywords:Keşfet> seçeneği, 2 fazla <DerivativeCardKeywords_152:\"Bereket\"> kartı içeren bir sete yükseltilir. Çekme Destene karıştırmak için 1 set seç. Bir \"Bereket\" kartı oynadıktan sonra, Embriyo Füzyonu +10 artar. Bu füzyon etkisi kaybedilen HP'ye göre artar, en fazla +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo [Arg2]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullandıktan sonra, bir sonraki <DerivativeCardKeywords_160:\"Mucize Bereket\">'in maliyeti -3 Arithmetica azalır ve her <FaxianKeywords:Keşfet> seçeneği, 1 fazla <DerivativeCardKeywords_152:\"Bereket\"> kartı içeren bir sete yükseltilir. Çekme Destene karıştırmak için 1 set seç."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo [Arg2]% Temel Aliemus kazanır. <ExaltIconKeywords:Uyanış>: \"Kızıl Ocak\" kullandıktan sonra, bir sonraki <DerivativeCardKeywords_160:\"Mucize Bereket\">'in maliyeti -3 Arithmetica azalır ve her <FaxianKeywords:Keşfet> seçeneği, 2 fazla <DerivativeCardKeywords_152:\"Bereket\"> kartı içeren bir sete yükseltilir. Çekme Destene karıştırmak için 1 set seç. Bir <Blessing:Bereket> kartı oynadıktan sonra, Embriyo Füzyonu +10 artar. Bu füzyon etkisi kaybedilen HP'ye göre artar, en fazla +100%."
  },
