  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Bir zamanlar, çocuk o kötü siyah çamuru kendinden söküp atmaya çalışmıştı — ama ne yaparsa yapsın, ister elleriyle parçalasın, ister bıçakla kesse, ister küt bir silahla vursun... biçimsiz kabus dağılmayı reddediyor, yalnızca daha da küstahlaşıyordu.\nSonunda, kendisiyle O'nun çoktan tamamen birleşip birbirinden ayrılamaz hale geldiğini nihayet kabullendi.\nO, onun gölgesi olmuştu."
  },
  Skill_145677_BattleDesc_0 = {
    Text = "Yeminini Bozan·Ogier <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Her turda Yeminini Bozan·Ogier'in \"Günahla Lekelenmiş Mızrak Ucu\" ile ilk hasar verişinde eşit miktarda <Corrosion:Aşınma> uygula. \"Savunma\"nın Kalkan Artışı %50 artar, 1 kart çek."
  },
  Skill_145677_BattleDesc_15 = {
    Text = "Yeminini Bozan·Ogier <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Her turda Yeminini Bozan·Ogier'in \"Günahla Lekelenmiş Mızrak Ucu\" ile ilk hasar verişinde eşit miktarda <Corrosion:Aşınma> uygula. \"Günahla Lekelenmiş Mızrak Ucu\"nun Temel HSR'ı %100 artar, ek olarak %200 Güç bonusundan yararlanır. \"Savunma\"nın Kalkan Artışı %100 artar, 1 kart çek."
  },
  Skill_145677_Desc_0 = {
    Text = "Yeminini Bozan·Ogier [Arg2]% Aliemus Üssü kazanır. <ExaltIconKeywords:Uyanış>: Her turda Yeminini Bozan·Ogier'in \"Günahla Lekelenmiş Mızrak Ucu\" ile ilk hasar verişinde eşit miktarda <Corrosion:Aşınma> uygula. \"Savunma\"nın Kalkan Artışı %50 artar, 1 kart çek."
