  },
  Skill_146013_AwakerSkillBackgroundStory = {
    Text = "Çok az, çok az zamanlarda Lotan kılıcını geri çekerdi.\nO iki renkli gözler soğukkanlılıkla değerlendiriyordu. Geri çekilmek, her zaman yalnızca daha iyi bir hamle için yapılırdı."
  },
  Skill_146013_BattleDesc_0 = {
