  Skill_146015_OverLimitUtlSkillDesc = {
    Text = "Kullanmak için <DerivativeCardKeywords_153:\"Büyük Kılıç: Balina Düşüşü\"> tüket. [Power:Arg3] <PowerIconKeywords:STR> kazan. En yüksek hasara sahip düşmana <Damage:[Damage:Arg1]> garantili Kritik Vuruş hasarı ver; bu hasar [Arg2]% Güç Bonusundan yararlanır. <DerivativeCardKeywords_153:\"Büyük Kılıç: Balina Düşüşü\">'nun hedefe sana verdirdiği her +1 hasar için, \"Mundus Kopuşu\" +[Arg4] hasar verir. <DerivativeCardKeywords_154:>"
  },
