  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "Ogier'in anıları D-fenomen nedeniyle parçalanmış durumda.\nBalodaki kahkahaları hatırlar ama balonun başkahramanının adını unutur; şövalye birliğindeki eğitimini hatırlar ama dükün onu bu kadar genç yaşta neden şövalye tayin ettiğini bilmez; demir süvarilerin altında can verdiğini hatırlar ama kimin gülümsemesini koruduğunu hatırlayamaz.\nKimse onu suçlayamazdı. Bir şövalyenin tüm sorumluluklarını yerine getirmişti—koruma iradesi uğruna hayatını feda etmek de dahil."
  },
  Skill_21615_Desc_0 = {
    Text = "Kendindeki <FragileIconKeywords:Fragile> durumunu dağıt. <Block:[Block:Arg1]> Kalkan elde et. [Power:Arg2] Geçici <PowerIconKeywords:STR> kazan."
  },
  Skill_21615_Desc_2 = {
    Text = "Takım şu anda <FragileIconKeywords:Kırılgan> Durumuna sahipse, onu dağıt ve <Block:[Block:Arg3]> Karakter Kalkanı elde et. <Block:[Block:Arg1]> Karakter Kalkanı elde et. [Power:Arg2] Geçici <PowerIconKeywords:STR> kazan."
  },
