  Skill_21615_OverLimitUtlSkillDesc_0 = {
    Text = "Kendi <FragileIconKeywords:Kırılgan> Durumunu dağıtır. <Block:[Block:Arg1]> puan Kalkan kazanır. [Power:Arg2] puan Geçici <PowerIconKeywords:Güç> kazanır. Kazanılan Kalkan %200 artar. Ogier'in verdiği hasar sayısı +1, 3 tur sürer."
  },
  Skill_21615_OverLimitUtlSkillDesc_2 = {
    Text = "Eğer <FragileIconKeywords:Kırılgan> Durumuna sahipsen, onu dağıt ve <Block:[Block:Arg3]> Kalkan kazan. <Block:[Block:Arg1]> Kalkan elde et. [Power:Arg2] Geçici <PowerIconKeywords:Güç> elde et. Elde edilen Kalkanı %200 artır. Ogier'in Hasar sayısı 3 tur boyunca +1."
