  Skill_3973_AwakerSkillBackgroundStory = {
    Text = "Sessizlik tarafından yutulmak üzereyken, boğulmuş bir hizmetçi gördüğünü sandı.\nHizmetçinin teni solgundu, gölde yüzen çürümüş bir nilüfer gibi; boynundaki yaralar mavimsi damarlar boyunca görünmeyen uzaklıklara uzanıyordu.\n\"Kedigözü kolyene bak,\" dedi ceset, \"Hepsi küle döndü. Küle döndü...\""
  },
  Skill_3973_Desc = {
    Text = "<Heal:[Heal:Arg1]> HP yenile ve <Block:[Block:Arg2]> Karakter Kalkanı kazan. Tur sonunda elde tutulursa, Arithmetica Maliyeti 1 artar ve hem HP yenileme hem de Karakter Kalkanı miktarı ikiye katlanır. En fazla [Arg3] kez yığılır."
