  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "\"Yaklaşın, utanmayın, bırakın şapka ustası kahkahanızın ve neşenizin tadını çıkarsın.\"\nUsta Casiah şapkasının kenarına hafifçe vurdu ve bir patlama ile büyük bir deste kurdele ve kart çıkardı.\n\"Kalbinizde kartınızı seçin. Şşş! Kimseye söylemeyin. Usta Casiah size yalnızca sizin olan kartı gösterecek.\""
  },
  Skill_3977_Desc_0 = {
    Text = "\"Vuruş\" olarak kabul edilir. <DimensionalSpaceIconKeywords:Ultra Space> içinden herhangi 1 kart seç ve Arithmetica Maliyeti’ni 2 azaltarak eline ekle. Rastgele <Damage:[Damage:Arg1]> Hasarı [Arg2] kez ver ve [Power:Arg3] Geçici <PowerIconKeywords:Strength> kazan."
  },
  Skill_3977_Desc_3 = {
    Text = "\"Darbe\" olarak kabul edilir. <DimensionalSpaceIconKeywords:Ultra Uzay> içinden herhangi 1 kart seç ve eline ekle; Arithmetica Maliyetini 2 azalt. Rastgele olarak [Arg2] kez <Damage:[Damage:Arg1]> Hasar ver ve [Power:Arg3] Geçici <PowerIconKeywords:Güç> kazan. <RippleKeywords:Artçı Sarsıntı>: Çekme Desteğine 1 adet <DerivativeCardKeywords_4:\"Kavrayış\"> karıştır."
  },
  Skill_3977_EffectNameList = {
