  Skill_3978_Name = {Text = "Teyakkuz"},
  Skill_3979_AwakerSkillBackgroundStory = {
    Text = "Şizofreni.\nBu terim ortaya çıkmadan çok önce, Herbert laboratuvarında sayısız tıbbi kayıt oluşturmuştu.\n24 şüphesiz bunların arasındaki başyapıttır; kişilikleri birbirini etkilemeden hızla çoğalır.\nBir bakıma zihni, gürültücü kiracılarla dolu kalabalık bir apartman dairesi gibidir."
