  Skill_3981_AwakerSkillBackgroundStory = {
    Text = "Miras alınan kan bağı, başkaları tarafından sapkınlık sayılıyor.\nAncak onun asaletine ve büyüklüğüne sıkı sıkıya inanarak bu acımasız dünyada hayatta kalınabilir.\nOrnn Amca'dan kalan o el yazması ve resim gibi güzel sualtı antik kenti, onun tek manevi desteği.\n\"Kan bağı patladığında, derin denizden bana mutlaka üstün güç bahşedilecek.\""
  },
  Skill_3981_Desc = {
    Text = "<Heal:[Heal:Arg3]> Can yenile ve kendinden <WeaknessIconKeywords:Semptom: Zayıflık> kaldır, tüm düşmanlara [Arg4] <plural value=\"[Arg4]\" singular=\"yığın\" plural=\"yığın\"> <VulnerabilityIconKeywords:Savunmasız> uygula. <TentacleInjurieIconKeywords:Dokunaç Hasarı> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Karşı Saldırı> +[Counterattack:Arg2]. Bir sonraki turun başlangıcına kadar, alınan her Saldırı için 1 Dokunaç'a karşı saldırı emri ver."
  },
  Skill_3981_EffectNameList = {
    Text = "İyileştirme,Dokunaç Hasarı,Sayaç"
