  Skill_4010_AwakerSkillBackgroundStory = {
    Text = "Helot bu tuhaf gücü ne zaman elde ettiğini hatırlayamıyordu.\nYıldızsız bir gecede, Helot hapishanenin çamurlu zemininde uyandı ve yanında kıvranan siyah bir çamur fark etti. Siyah çamur yeni uzuvlar gibi davranarak zincirlerini kırdı.\nYanındaki hücrede hapsedilen yaşlı serfi hatırladı; onun için yalvarmış ve sonunda hapse atılmıştı. Koşarak kontrol etmeye gitti ama yalnızca kuruyan kan lekeleri buldu.\nO, babasıydı.\nDurmaksızın süren çalışma onun canını almamıştı, acımasız kırbaçlar da—canını alan onun merhamet dilenmesi, muhbirlerin iftirasıydı ve yöneticilerin adalete karşı körlüğüydü...\nGözleri çoktan kurumuştu ve şimdi onlardan akan—yalnızca nefretle dolu siyah çamurdu."
  },
  Skill_4010_BattleDesc = {
    Text = "Mevcut HP’nin [Arg1]%’ini kaybet ([Arg3]). Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver ve verilen Hasar kadar <BleedingIconKeywords:Kan Akıtma> uygula. Eline rastgele 2 Uyanışçı \"Darbe\" kartı ekle; bu kartlarda <DepleteIconKeywords:Tüketme> vardır. Bu kart\"Vuruş\"olarak sayılır."
  },
  Skill_4010_Desc = {
    Text = "Mevcut Canının [Arg1]%’ini kaybet. Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver ve aynı miktarda <BleedingIconKeywords:Kan Akıtma> uygula. 2 rastgele Uyandıran’ın \"Vuruş\"kartını üret, ele al ve onlara <DepleteIconKeywords:Tüketme> ekle. Bu kart\"Vuruş\"olarak sayılır."
  },
