  Skill_4055_AwakerSkillBackgroundStory = {
    Text = "Uçsuz bucaksız okyanusta, yalnız bir gemi dalgalarla sallanıyor.\nDua ediyorlar, yalvarıyorlar, yakarıyorlar; Beyaz Kutsal Bakire'nin onları denizden uzaklaştırıp yurtlarına geri götürmesini umuyorlar.\nAna direğin üzerinde, beyaz elbiseli bir kız başını kaldırıp beyaz bir kuş görüyor.\n\"Dümeni bana verin, sizi eve götüreceğim.\""
  },
  Skill_4055_BattleDesc_0 = {
    Text = "Kendindeki <HeavyInjuryKeywords:Ağır Yıkım> durumunu dağıt, <Heal:[Heal:Arg1]> HP yenile ve 1 Arithmetica kazan. Bu savaşta ölümcül Hasar aldığında Canlanma gerçekleşir ve [Arg2]% (<Heal:[Arg3]>) HP yenilenir. Her savaşta yalnızca bir kez tetiklenebilir."
  },
  Skill_4055_BattleDesc_3 = {
    Text = "Kendi üzerindeki <HeavyInjuryKeywords:Blighten> durumunu dağıtır, <Heal:[Heal:Arg1]> HP yeniler ve 1 Arithmetica kazanır. Bu savaş sırasında ölümcül Hasar aldığında Canlanma gerçekleşir, [Arg2]% (<Heal:[Arg3]>) HP yeniler ve tüm Uyanışçılara <Energy:[Energy:Arg4]> Aliemus bahşeder. Bu Canlanma Etkisi 6 tur sonra yeniden tetiklenebilir."
  },
  Skill_4055_Desc_0 = {
    Text = "Kendindeki <HeavyInjuryKeywords:Ağır Yıkım> durumunu dağıt, <Heal:[Heal:Arg1]> HP yenile ve 1 Arithmetica kazan. Bu savaşta ölümcül Hasar aldığında diril ve HP’ni [Arg2]% yenile. Her savaşta yalnızca bir kez tetiklenebilir."
  },
  Skill_4055_Desc_3 = {
