  Skill_4055_OverLimitUtlSkillDesc_0 = {
    Text = "<Heal:[Heal:Arg1]> puan Can İyileştirir ve 1 Arithmetica kazanır, kendi <HeavyInjuryKeywords:Ağır Yıkım> Durumunu dağıtır. Bu savaşta ölümcül Hasar alındığında Diriliş gerçekleşir, [Arg2]% (<Heal:[Arg3]>) Can İyileştirir, her savaşta yalnızca 1 kez tetiklenebilir. İyileşme Takviyesi %50 olan 3 adet \"Bembeyaz Rüya\" kartını Ele alır ve Tüketim ekler."
  },
  Skill_4055_OverLimitUtlSkillDesc_3 = {
    Text = "<Heal:[Heal:Arg1]> HP yeniler ve 1 Arithmetica kazanır, kendi üzerindeki <HeavyInjuryKeywords:Blighten> Durumunu dağıtır. Bu savaşta ölümcül Hasar alınırsa diril, [Arg2]%(<Heal:[Arg3]>) HP yenile ve tüm Uyanışçıların <Energy:[Energy:Arg4]> Aliemus kazanmasını sağla. Tetiklendikten sonra, diriliş etkisinin yeniden uygulanabilmesi için 6 turluk bir aralık gerekir. Ele 3 adet, İyileştirmeyi %50 artıran \"Tintless Dream\" kartı yerleştir ve Tüketme uygula."
