  Skill_4065_BattleDesc_0 = {
    Text = "[Arg1] Geçici <AlertIconKeywords:Alarm> elde et. <Posse:[Arg2]> Keyflare elde et. Kendi <FragileIconKeywords:Kırılgan> durumunu dağıt. Bir kart <DimensionalSpaceIconKeywords:Ultra Uzay>a her girdiğinde, <DerivativeCardKeywords_13:\"Serbest Bırak: Meka\">ya dönüş."
