  Skill_4065_BattleDesc_1 = {
    Text = "[Arg1] Geçici <AlertIconKeywords:Alert> elde et. <Posse:[Arg2]> Anahtar Alevi elde et. Kendi üzerindeki <FragileIconKeywords:Fragile> Durumunu dağıt. Eline Erica’ya ait, üzerinde <DepleteIconKeywords:Tüketme> bulunan 1 \"Savunma\" yerleştir. Bir kart <DimensionalSpaceIconKeywords:Ultra Uzay>a girdiğinde, <DerivativeCardKeywords_13:\"Serbest Bırak: Meka\">ya dönüş."
  },
  Skill_4065_Desc_0 = {
