  Skill_4075_AwakerSkillBackgroundStory = {
    Text = "Nymphaea çiçekleri sever. Edebiyatın yanı sıra, başucundaki tek yoldaşları onlardır.\nEbeveynlerinin ölümünden beri, kimse ona düzenli olarak teselli buketleri getirmemiştir.\nSon zambaklar zamanla solmuştur.\nBu yüzden, onları tereddüt etmeden kendi cenazesine götürdü.\nBalıklar ışıkla dans etti, mercanlar saplar gibi büyüdü ve dalgalar baktığı uzak ufka doğru yükseldi."
  },
  Skill_4075_BattleDesc_0 = {
    Text = "Tüm düşmanlara [Poison:Arg1] yığın <IntoxicationIconKeywords:Zehir> uygula ve onların <IntoxicationIconKeywords:Zehir> etkilerinin [Arg3]%’sini tetikle. [Power:Arg2] puan <PowerIconKeywords:GÜÇ> kazan."
