  Skill_4137_AwakerSkillBackgroundStory = {
    Text = "Tümdengelim, mantıksal akıl yürütmenin bir biçimidir; ancak doğru öncülü kavrayan kişi, isabetli bir sonuca varabilir.\nMüfettiş olmadan önce Ramona, dünyayı anlamak için zaten tümdengelim kullanıyordu.\nYeterince macera yaşadıktan sonra, belki de tümevarımı kullanmayı düşünmeye başlayacaktır."
  },
  Skill_4137_Desc_0 = {
    Text = "<Posse:[Arg1]> Anahtar Alevi kazan. Çekme destesinden veya Atılmış Kart Deste­sinden 1 kart seç, eline ekle ve Arithmetica Maliyetini 0'a düşür."
  },
  Skill_4137_Desc_3 = {
    Text = "<Posse:[Arg1]> Keyflare elde et. Çekme destesinden veya Atılmış Kart Desteğinden 1 kart seçip eline ekle ve Arithmetica Maliyetini 0’a düşür. Çekme destesine 1 adet <DerivativeCardKeywords_4:\"Insight\"> karıştır."
  },
  Skill_4137_EffectNameList = {
    Text = "Gümüş Anahtar Şarjı"
  },
  Skill_4137_Name = {
    Text = "Mundus Fermanı"
  },
  Skill_4137_OverLimitUtlSkillDesc_0 = {
    Text = "<Posse:[Arg1]> puan S-Enerjisi kazanır. Çekme Destesi veya Atılmış Kart Destesi'nden 1 kart seçerek Ele alır ve Arithmetica Maliyetini 0 yapar. <WeaknessIconKeywords:Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> tüm düşmanlar 1 tur, bir sonraki kullanılan Müfreze 2 kez etki eder."
  },
  Skill_4137_OverLimitUtlSkillDesc_3 = {
    Text = "<Posse:[Arg1]> Keyflare elde et. Çekme destesinden veya Atılmış Kart Desteğinden 1 kart seç ve eline ekle; Arithmetica Maliyetini 0'a düşür. Çekme destesine 1 adet <DerivativeCardKeywords_4:\"Kavrayış\"> karıştır. Tüm düşmanlara 1 tur boyunca <WeaknessIconKeywords:Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygula. Bir sonraki Serbest bırakacağın Çete iki kez etkisini gösterir."
  },
  Skill_4138_AwakerSkillBackgroundStory = {
    Text = "Ramona on yaşındayken, savaş eğitimi almak istediğini dile getirdi.\nBu, şövalye oyunları oynamakla ilgili değildi; fakat üvey babasının savurganlığını ve israfını gördükten sonra, kız yaklaşan iflas ihtimaline karşı hazırlanmaya karar verdi.\n\"Elbette kraliçenin muhafızı olmanın ücreti, karakoldaki maaştan daha yüksektir, değil mi?\""
  },
  Skill_4138_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> Hasarını [Arg2] kez ver. Oynandıktan sonra, \"Kraliçenin Kılıcı\"nın Hasar sayısını [Arg3] kezle sınırlı olmak üzere 1 artır. [Arg7] Geçici Diyar Ustalığı kazan."
  },
  Skill_4138_Desc_1 = {
    Text = "<Damage:[Damage:Arg1]> Hasar [Arg5] kez ver, her vuruş için [Power:Arg4] Geçici <PowerIconKeywords:Güç> kazan. Oynadıktan sonra, \"Kraliçenin Kılıcı\" vuruş sayısını maksimum [Arg6] kez olmak üzere +1 artır. [Arg7] Geçici Diyar Ustalığı kazan. <RippleKeywords:Artçı Sarsıntı>: Ramona'nın Gümüş Anahtar Şarjının %300'ü kadar S-Enerjisi kazan."
  },
  Skill_4138_Desc_3 = {
    Text = "<Damage:[Damage:Arg1]> Hasar [Arg5] kez ver, her vuruş için [Power:Arg4] Geçici <PowerIconKeywords:Güç> kazan. Oynadıktan sonra, \"Kraliçenin Kılıcı\" vuruş sayısını maksimum [Arg6] kez olmak üzere +1 artır. [Arg7] Geçici Diyar Ustalığı kazan. <RippleKeywords:Artçı Sarsıntı>: Ramona'nın Gümüş Anahtar Şarjının %300'ü kadar S-Enerjisi kazan."
