  Skill_4144_AwakerSkillBackgroundStory = {
    Text = "Eğer efendinin emriyse, Lily o koca herifi fırlatabilir.\nAcıdan korkmaz.\nAcı sadece güçtür; acı çılgınlığı besler. Lily acıdan korkmaz, o da korkmaz.\nBu yüzden, efendinin düşmanlarını yok etmesine mutlaka yardım edecek."
  },
  Skill_4144_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver, hedefin <IntoxicationIconKeywords:Zehir>inin [Arg3]%’sini tetikle. Eğer Kritik Vuruş gerçekleşirse, tetikleme oranı [Arg4]%’ye çıkar. Bu bir \"Darbe\" olarak kabul edilir. Her bir <PainWord:Tahammül> yığını için Hasarı 2 artır ve kullanım sonrası <PainWord:Tahammül>ü kaldır."
  },
  Skill_4144_Desc_2 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver, hedefin <IntoxicationIconKeywords:Zehir> durumunun [Arg3]%’sini tetikle. Eğer bir Kritik Vuruş gerçekleşirse, tetiklenme oranı [Arg4]%’ye çıkar. Bir Darbe olarak kabul edilir. Her bir <PainWord:Endure> yığını için Hasarı 2 artır ve kullanım sonrası <PainWord:Endure>’u kaldır. Bu kartın Kritik Oranı %20 artar."
  },
  Skill_4144_Desc_3 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver, hedefin <IntoxicationIconKeywords:Zehir> durumunun [Arg3]%’sini tetikle. Eğer bir Kritik Vuruş gerçekleşirse, tetiklenme oranı [Arg4]%’ye çıkar. \"Darbe\" olarak kabul edilir. Her bir <PainWord:Endure> yığını için Hasarı 2 artır ve kullanım sonrası <PainWord:Endure> yığınlarının yarısını kaldır. Bu kartın Kritik Oranı %20 artar."
