  },
  Skill_4152_AwakerSkillBackgroundStory = {
    Text = "Kan dökülmesi, cesetler ya da delici acı—hiçbirinin önemi yok.\nBunlar, ilahi krallığın geri dönüşü için önemsiz fedakârlıklar.\nO sadece seçilmiş kişi olmadığı için, kafese hapsedilen kız olmadığı için pişmanlık duyuyor."
  },
  Skill_4152_Desc_0 = {
    Text = "<Energy:[Energy:Arg2]> Aliemus elde etmesi için 1 başka Uyanan seç. <O07CardKeyWord:Ritüel>: [Arg4]/[Arg5]/[Arg6] Aliemus kazan."
  },
  Skill_4152_Desc_2 = {
    Text = "Başka 1 Uyanışçı seç; <Energy:[Energy:Arg2]> Aliemus elde etsin, Diyar Ustalığı +[Arg3]. <O07CardKeyWord:Ritual>: Fazladan [Arg4]/[Arg5]/[Arg6] Aliemus kazan."
