  },
  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Dinle, bu kendisi için çalan ölüm çanıdır.\nNe çılgın bir arayıcı, ne de kaybolmuş bir ruh; o sadece kendi sonunu seçti.\nSolan yapraklar ritüelinde dans eder ve çılgına dönmüş deniz rüzgârı ağıtını inletir.\nGüçlü çan sesinden sonra, dünya kısa ve ölümcül bir sessizliğe gömüldü."
  },
  Skill_4154_Desc_0 = {
    Text = "Tüm düşmanlara [Poison:Arg1] yığın <IntoxicationIconKeywords:Zehir> uygula, [Arg2] tur boyunca sürer; <WeaknessIconKeywords:Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygula."
  },
  Skill_4154_Desc_1 = {
