  Skill_4155_AwakerSkillBackgroundStory = {
    Text = "Sonsuzluktan, cehaletten doğan, korkudan kaynaklanan.\nThais'in damarlarında akan ilkel bir içgüdüdür.\nUnutulmaz bir fedakârlıkta, genç Thais'e bu içgüdü aşılandı.\nİrade, duygu ve hatta kişilik yabancı bir varlık tarafından değiştirildi—\nGeriye kalan, yaşamın ortak ipliğiydi: ölüm korkusunun içgüdüsel hissi."
  },
  Skill_4155_BattleDesc_0 = {
    Text = "<EmbryoFusionIconKeywords:Embriyo Füzyonu> +[Blood:Arg1], <Posse:[Arg2]> S-Enerjisi kazan. Seç: <B01AFKeyWord1:Korkunun Kanı>, <B01AFKeyWord2:Çürüme Kanı>, <B01AFKeyWord3:Birleşme Kanı><DerivativeCardKeywords_149:><DerivativeCardKeywords_150:><DerivativeCardKeywords_151:>"
