  Skill_4156_BattleDesc_0 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan. <Energy:[Energy:Arg2]> Aliemus kazan. \"Savunma\" olarak kabul edilir. <TransitionIconKeywords:Leap>: Duygu durumunu \"Keder\"e geçir."
