  },
  Skill_4156_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan. Horla <Energy:[Energy:Arg2]> Aliemus kazanır. \"Savunma\" olarak kabul edilir.<TransitionIconKeywords:Leap>: Duygu durumunu \"Keder\"e geçir. Tüketilen her 'Keder' Metaforu yığını için <Heal:[Heal:Arg3]> HP yenile."
