  Skill_4160_AwakerSkillBackgroundStory = {
    Text = "Besançon'daki hizmetçinin gözünde hanımefendisi biraz tuhafdı.\nŞiir okumaktan hoşlanmazdı, piyano da çalmamıştı hiç.\nGeçmişe ait şeyler onu büyülerdi. Kurumuş bir yaprağa dalgın dalgın bakardı... sonra aniden yerinden fırlayıp odasına koşardı—güm! güm! güm!\n\"Ah, bizim küçük sanatçımız!\" diye iç geçirdi hizmetçi, \"Onunla bir duvarcı arasında ne fark var ki?\""
  },
  Skill_4160_Desc_0 = {
