  Skill_4167_AwakerSkillBackgroundStory = {
    Text = "Bir salon düzenlemek kolay bir iş değildir. İçecek seçimi, tarif belirleme ve hatta garson seçimi bile bizzat ilgilenmeyi gerektirir.\nNeyse ki Sorel, takipçilerinden yeterli özgürlük ve ayrıcalık elde etmiştir."
  },
  Skill_4167_Desc_0 = {
    Text = "Sorel <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: [Power:Arg2] <PowerIconKeywords:GÜÇ> kazan. Sorel'in verdiği her Hasar örneği başına [Power:Arg3] Geçici <PowerIconKeywords:GÜÇ> kazan."
  },
  Skill_4167_Desc_15 = {
    Text = "Sorel <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: [Power:Arg2] <PowerIconKeywords:GÜÇ> kazan. Sorel her Hasar verdiğinde, [Power:Arg3] Geçici <PowerIconKeywords:GÜÇ> kazan, Sorel'in Geçici Final Hasarı +%2 ve diğer Uyandırıcıların Geçici Final Hasarı +%1. Geçici Final Hasar artışı tur başına en fazla [Arg4] <plural value=\"[Arg4]\" singular=\"kez\" plural=\"kez\"> etki eder."
