  Skill_4177_AwakerSkillBackgroundStory = {
    Text = "O aralıklı görünen iki sıra üçgen dişten korkma, içeri girdikten sonra bir daha hiç çıkmayan Beyaz Tavşan Hanım için de endişelenme—Silindir Şapkalı Bey, bizzat Usta Casiah tarafından eğitilmiş profesyonel bir büyülü eşyadır ve asla rastgele ısırmaz."
  },
  Skill_4177_Desc_0 = {
    Text = "<Energy:[Energy:Arg1]> Aliemus kazan. Elindeki Semptom ve Durum Kartlarını Atılmış Kart Destesi’ne gönder, elde kalan diğer kartları Çekme Destesi’ne karıştır, sonra aynı sayıda kart çek. <TransitionIconKeywords:Sıçrama>: \"Puff!\"ın Arithmetica Maliyetini iade et."
  },
