  Skill_4233_AwakerSkillBackgroundStory = {
    Text = "Nazik deniz suyu solmuş yaprakları taşır, nilüferler gibi dalgacıklar açtırır.\nGardını düşürürsen, sakin görünüşüne aldanırsın. Huzurlu ay ışığı altındaki hışırtılı gelgitler aslında yutup yok eden bir gücü gizler.\nTıpkı onun aşkı ve nefreti gibi, asla yüzeyde gösterilmez ama kabaran dalgalarda şiddetle yankılanır."
  },
  Skill_4233_Desc_0 = {
    Text = "En yüksek HP’ye sahip düşmana <Damage:[Damage:Arg1]> Hasar ver ve aynı miktarda <IntoxicationIconKeywords:Poison> uygula; bu, 2x <PowerIconKeywords:STR> bonusundan yararlanır."
