  Skill_4239_AwakerSkillBackgroundStory = {
    Text = "Tanrı'nın yönetimi altında halk, Büyük Başrahibe'yi hiç şüphesiz seviyordu.\nHerkes onun bağlılığını, çalışkanlığını ve fedakârlığını görebiliyordu.\nBu yüzden birçoğu onu gizlice Ana Tanrıça ile eşdeğer tutuyordu— fısıldanacak bir duygu, ama asla Miryam'ın kulağına gitmemeli."
  },
  Skill_4239_Desc_0 = {
    Text = "Eline [Arg4] <O07CardKeyWord2:\"Ayin\"> yerleştir, tüm düşmanlara [Poison:Arg5] <IntoxicationIconKeywords:Zehir> uygula. Dokunaç Duruşuna göre etkiler kazan: Yükselen Dalgalar: [Power:Arg1] <PowerIconKeywords:STR> ve [TentaclePower:Arg1] <TentacleInjurieIconKeywords:Dokunaç Hasarı> kazan; Sakin Deniz: diğer Uyananlar [Energy:Arg2] <Energy:Aliemus> kazanır; Azgın Dalgalar: tüm düşmanlarda <IntoxicationIconKeywords:Zehir> etkisinin [Arg3]%’sini tetikle."
  },
  Skill_4239_Desc_3 = {
    Text = "Eline [Arg4] <O07CardKeyWord2:\"Ayin\"> yerleştir, tüm düşmanlara [Poison:Arg5] <IntoxicationIconKeywords:Zehir> uygula. Dokunaç Duruşuna göre etkiler kazan: Yükselen Dalgalar: [Power:Arg1] <PowerIconKeywords:STR> ve [TentaclePower:Arg1] <TentacleInjurieIconKeywords:Dokunaç Hasarı> kazan; Sakin Deniz: diğer Uyananlar [Energy:Arg2] <Energy:Aliemus> kazanır; Azgın Dalgalar: tüm düşmanlarda <IntoxicationIconKeywords:Zehir> etkisinin [Arg3]%’sini tetikle."
