  Skill_4284_AwakerSkillBackgroundStory = {
    Text = "Acemi askerlere her zaman şunu söyler: yorgun olsanız da, zayıf olsanız da silahınızı asla bırakmayın. Onun en yakın yoldaşınız ve en güçlü Kalkanınız olmasına izin verin.\nSavaş alanında yalnızca yeterince tetikte kalanlar hayatta kalır."
  },
  Skill_4284_BattleDesc_0 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı [Arg2] kez kazanır. Tur sonunda, Elde ise, bir sonraki oynanışta bir kez daha Karakter Kalkanı üretir. Tüm Uyandırıcılardan <CardKeyWord:Mühürlü> durumunu gider."
  },
  Skill_4284_BattleDesc_1 = {
    Text = "[Arg2] kez <Block:[Block:Arg1]> Karakter Kalkanı kazan. Tur sonunda, eğer eldeyse, bir sonraki oynanışında 1 kez daha Karakter Kalkanı üretir. Tüm Uyananlardan <CardKeyWord:Sealed> etkisini gider. \"Savunma\" olarak kabul edilir."
  },
  Skill_4284_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı kazan. Tur sonunda Elde ise, bir sonraki oynanışında Karakter Kalkanı’nı 1 kez daha üret. Tüm Uyananlar’ın <CardKeyWord:Sealed> durumlarını dağıt."
  },
  Skill_4284_Desc_1 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan. Tur sonunda eldeyse, bir sonraki oynanışında Kalkan üretimini 1 kez daha gerçekleştir. Tüm Uyananların <CardKeyWord:Sealed> durumlarını dağıt. \"Savunma\" olarak kabul edilir."
