  Skill_4289_Name = {Text = "Yoklama"},
  Skill_4290_AwakerSkillBackgroundStory = {
    Text = "Zafer alayı Romalılar için her zaman görkemli bir kutlama olmuştur.\nHavada uçuşan beyaz güvercinler, defne yaprakları ve altın konfetiler... tüm bunlar savaşçılarla ilgilidir, ama aynı zamanda ilgisizdir.\nGalya, İskenderiye ve Partya'dan gelen esirlerle birlikte, ağır bir çarmıha bağlanıp sokaklarda dolaştırıldı.\nBu zafer alayının vazgeçilmez bir parçasıdır. Savaşçı acımasızca alay edilir, sırf merhum imparatorun kanlı suç ortağı sayıldığı için.\nUtanç, öfke ya da nefret mi? Hayır, bunların hiçbiri.\nSavaşçının duyguları yok, düşünceleri yok.\nSadece kan kokusu alıyor."
  },
  Skill_4290_BattleDesc_0 = {
    Text = "Uvhash <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Uvhash <CardKeyWord:Mühür> etkisinden etkilenmez. Kritik oranı ve kritik hasar %[Arg2] artar. Can %25'in altındaysa etkiler iki katına çıkar."
