  Skill_4305_Name = {Text = "Aliemus"},
  Skill_4306_AwakerSkillBackgroundStory = {
    Text = "O'nun adına yeryüzünde hareket edecek.\nO'nun hak ettiği şanı kazanacak.\nYıkım zamanında, başka kimsenin dayanamayacağı acıya katlanacak.\nO, İnfazcı'dır."
