  Skill_4306_Desc_0 = {
    Text = "Miryam <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Dokunaç Sınırı ve Dokunaç Sayısı +1. Tüm düşmanlara 1 yığın <WeaknessIconKeywords:Semptom: Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygular. Miryam'ın \"Vuruş\" ve \"Yüce Ateş Sunağı\" Kritik Oranı +%100. Ele 1 <O07CardKeyWord4:\"Sapkın İnanç\"> yerleştirir."
  },
  Skill_4306_Desc_15 = {
    Text = "Miryam <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Dokunaç Sınırı ve Dokunaç Sayısı +1. Tüm düşmanlara 1 yığın <WeaknessIconKeywords:Semptom: Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygular. Miryam'ın \"Vuruş\" ve \"Yüce Ateş Sunağı\" Kritik Oranı +%100. Ele 1 <O07CardKeyWord4:\"Sapkın İnanç\"> yerleştirir. Her 2 \"Ayin\" kartı çevrildiğinde, ele 1 \"Tanrı'nın Diyarı İllüzyonu\" yerleştirir."
