  Skill_4310_Desc = {
    Text = "<Damage:[Damage:Arg1]> Hasarını [AttackTimes:Arg2] kez ver. Rakibin tur sonuna kadar [Arg3] <PowerIconKeywords:GÜÇ> kaybetmesini sağla."
  },
  Skill_4311_AwakerSkillBackgroundStory = {
    Text = "Yumuşak bir dokunuş sana sevgiyi hissettirir mi?\nSıcak nefesler seni bana özletir mi?\nİnciler ve ipekle çevrili bu okşama, sana bir hediye mi?"
  },
  Skill_4311_Desc_0 = {
    Text = "Bu Uyanan ve seçilen diğer Uyanan'a <Energy:[Energy:Arg1]> Aliemus vermek için 1 başka Uyanan seç. [Power:Arg2] <PowerIconKeywords:GÜÇ> elde et."
