  Skill_4313_Desc = {
    Text = "[Arg1] yığın <IntoxicationIconKeywords:Zehir> uygula."
  },
  Skill_4313_Name = {Text = "Zehir"},
  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "Kanı Onlar yüzünden kaynadı, zihni Onlar yüzünden fokurdadı.\nBu yabancı döllerin dileğini yerine getirip getiremeyeceği önemli değildi, Boşluk'ta hayatta kalıp kalamayacakları da.\nThais, her Saflığın Varisi'nin doğuşunu şefkatle karşıladı."
  },
  Skill_4314_Desc_0 = {
    Text = "[<DevouredIconKeywords:Yutma>: Diğer Uyandırıcılara <Energy:[Energy:Arg1]> Aliemus ver.] Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver ve verilen Hasarın [Arg3]%'i kadar <BleedingIconKeywords:Kanama>, verilen Hasarın [Arg4]%'i kadar <IntoxicationIconKeywords:Zehir> uygula ve verilen Hasarın [Arg5]%'i kadar <RetaliateIconKeywords:Karşı Saldırı> kazan. Elde Türetilmiş olmayan 1 Komut Kartı seç, <DepleteIconKeywords:Tükenme>, <NothingnessIconKeywords:Yanılsama> ve -[Arg6] Arithmetica Maliyeti ile [Arg7] <plural value=\"[Arg7]\" singular=\"Temel Kopya\" plural=\"Temel Kopya\"> ele ekle."
  },
  Skill_4314_EffectNameList = {
    Text = "Aliemus,Hasar,Kanama%,Zehir%,Karşı Saldırı%"
  },
  Skill_4314_Name = {
    Text = "Bereket Ritüeli"
  },
  Skill_4314_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Yutma>: Diğer Uyandırıcılara <Energy:[Energy:Arg1]> Aliemus ver.] Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver ve verilen Hasarın [Arg3]%'i kadar <BleedingIconKeywords:Kanama>, verilen Hasarın [Arg4]%'i kadar <IntoxicationIconKeywords:Zehir> uygula ve verilen Hasarın [Arg5]%'i kadar <RetaliateIconKeywords:Karşı Atak> kazan. Elde bulunan Türetilmiş olmayan 1 Komut Kartı seç, <DepleteIconKeywords:Tükenme>, <NothingnessIconKeywords:Yanılsama> ve -[Arg6] Arithmetica Maliyeti ile [Arg7] <plural value=\"[Arg7]\" singular=\"Temel Kopya\" plural=\"Temel Kopya\"> ele ekle. Sonraki 3 tur boyunca, tur başında 1 \"Embriyo\"yu \"Saflığın Varisi\"ne dönüştür. Eğer \"Embriyo\" yoksa, <EmbryoFusionIconKeywords:Embriyo Füzyonu> +[Blood:Arg8], Embriyo Füzyonu artış efektlerinden etkilenmez."
  },
  Skill_4314_PropertyNameList = {
