  },
  Skill_4315_AwakerSkillBackgroundStory = {
    Text = "Efendiyi koru. Efendiyi koru. Efendiyi koru.\nKorkak canavarlar, tıpkı onun gibi, yaşama sahipmiş gibi görünüyor ama bilinçten yoksunlar.\nKaranlık balçık onun uşaklarına dönüşüyor, gece gündüz durmaksızın komutlarla yönlendiriliyor."
  },
  Skill_4315_Desc_0 = {
    Text = "Lily <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyandır>: Tur başında, Maksimum HP'nin %10'u kadar HP yenile:<PainWord:Dayan>. Lily bir Kalkan uyguladığında, en yüksek HP'ye sahip düşmana [Poison:Arg2] yığın <IntoxicationIconKeywords:Zehir> uygula."
  },
  Skill_4315_Desc_15 = {
    Text = "Lily <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Tur başında, Maksimum canın %10'una eşit <PainWord:Tahammül> kazan. Lily bir Kalkan uyguladığında, en yüksek Can'a sahip düşmana [Poison:Arg2] yığın <IntoxicationIconKeywords:Zehir> uygula. Taşkınlık, bu turda alınan her darbeyle bir sonraki \"Koruma Darbesi\"nin <PainWord:Tahammül> tüketim etkisini %40 artırır, en fazla 5 kez yığılır."
  },
