  Skill_4322_AwakerSkillBackgroundStory = {
    Text = "Güvelerin beyni yoktur ve tamamen içgüdüyle hareket ederler.\nMadem öyle, bu beyinsiz aptallara arzuladıkları şeyi gösterelim.\nBu, masumiyetle ve hayranlıkla dolu genç bir kızın hayalidir."
  },
