  },
  Skill_4329_AwakerSkillBackgroundStory = {
    Text = "Vatanının yıkımına tanık olduktan sonra bile, bildiği her şey çözülmenin yutucu gücü altında yok olduktan sonra bile, aramasından vazgeçmiyor. Konum belirleyici bir arama ışığı yayarak, onunla aynı yurdu paylaşanları bulmaya çalışıyor.\nBiri olmalı, mutlaka biri olmalı."
  },
  Skill_4329_BattleDesc_0 = {
    Text = "<Block:[Block:Arg3]> Kalkan kazan, eldeki tüm kartları at. <TransitionIconKeywords:Sıçrama>: Artık kart atmazsın, <Block:[Block:Arg4]> Kalkan kazan ve 1 kart çek."
  },
  Skill_4329_BattleDesc_2 = {
    Text = "<Block:[Block:Arg3]> Kalkan kazan, eldeki tüm kartları at; atılan her kart için <Block:[Block:Arg2]> Gecikmeli Kalkan kazan. <TransitionIconKeywords:Sıçrama>: Artık kart atmazsın, <Block:[Block:Arg4]> Kalkan kazan ve 2 kart çek."
  },
  Skill_4329_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan, elindeki tüm kartları at ve atılan her kart için kazanılan Kalkan %50 artar. <TransitionIconKeywords:Leap>: Kartları atma ve 1 kart çek; kazanılan Kalkan %100 artar."
  },
  Skill_4329_Desc_2 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan, tüm eldeki kartları at; atılan her kart için Kalkan Üretimi %50 artar ve <Block:[Block:Arg2]> puan Gecikmeli Kalkan kazanırsın. <TransitionIconKeywords:Leap>: Artık kart atmazsın ve 2 kart çekersin, Kalkan Üretimi %100 artar."
