  Skill_4333_Desc = {
    Text = "[Arg1] <PowerIconKeywords:STR> elde et, <Block:[Block:Arg2]> Karakter Kalkanı elde et."
  },
  Skill_4334_AwakerSkillBackgroundStory = {
    Text = "Kara balçıkta açan bir tomurcuk. Bir zamanlar bahçıvan tarafından el üstünde tutulmuş, yağmur ve çiğle beslenmiş.\nŞimdi tek başına açıyor; narin tenini kesen şiddetli rüzgârlara, zayıf bedenini döven sağanak yağmurlara, yüzeyini kesen keskin bıçaklara ve iliğini delen uzun iğnelere katlanarak.\nNe olursa olsun, içindeki dev canavar acıyı onun yerine çekecek.\nBelki de şu an sahip olduğu tek yoldaş o dev canavar. Bundan sonra, yalnızca onunla birlikte yaşayabilir..."
  },
  Skill_4334_BattleDesc_0 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et. <PainWord:Endure> yığınlarının [Arg2]%’ini ([Arg3]) HP olarak iyileştir ve <PainWord:Endure>’ı kaldır. Her saldırı, saldırgana 1 tur boyunca [Poison:Arg4] yığın <IntoxicationIconKeywords:Poison> uygular."
  },
  Skill_4334_BattleDesc_3 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et. <PainWord:Endure> yığınlarının sayısına göre HP’nin [Arg2]%’ini ([Arg3]) yenile ve <PainWord:Endure>’ın yarısını kaldır. Her saldırıya uğradığında, saldırgana 1 tur boyunca [Poison:Arg4] yığın <IntoxicationIconKeywords:Poison> uygula."
  },
  Skill_4334_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Kalkan elde et. <PainWord:Dayan> yığınlarının [Arg2]%’ini HP olarak geri yükle ve <PainWord:Dayan>ı kaldır. Her saldırıya uğradığında, saldırgana 1 tur boyunca [Poison:Arg4] yığın <IntoxicationIconKeywords:Zehir> uygula."
  },
  Skill_4334_Desc_3 = {
