  Skill_4334_tempBattleDesc_3 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan. <PainWord:Tahammül> yığınlarının [Arg2]%'si ([Arg3]) kadar Can yenile ve <PainWord:Tahammül> yığınlarının yarısını kaldır. Alınan her Saldırı için saldırgana 1 tur süren [Poison:Arg4] yığın <IntoxicationIconKeywords:Zehir> uygula. Bu turda alınan her Saldırı, bir sonraki \"Koruma Darbesi\"nin <PainWord:Tahammül> tüketim Etkisini %40 artırır, en fazla 5 kez yığılır."
  },
  Skill_4334_tempOverLimitUtlSkillDesc_1 = {
    Text = "<Block:[Block:Arg1]> puan Kalkan kazanır. <PainWord:Tahammül> yığını [Arg2]% ([Arg3]) kadar Can İyileştirir ve <PainWord:Tahammül>'ü kaldırır. Her saldırı alındığında saldırgana [Poison:Arg4] yığın <IntoxicationIconKeywords:Zehir> uygular, 1 tur sürer. Bu savaşta Tahammül üst sınırı %100 artar ve maksimum cana eşit Tahammül kazanılır. Tüketim eklenmiş 2 adet \"Koruma Darbesi\" kartını Ele alır."
  },
  Skill_4334_tempOverLimitUtlSkillDesc_2 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et. [Arg2]%([Arg3]) oranında <PainWord:Tahammül> yığınını CP olarak geri kazan ve <PainWord:Tahammül>ün yarısını kaldır. Her saldırıya uğradığında, saldırgana 1 tur boyunca sürecek şekilde [Poison:Arg4] yığın <IntoxicationIconKeywords:Zehir> uygula. Bu Savaşta, Tahammül’ün azami sınırı %100 artar ve Azami CP’ne eşit miktarda Tahammül kazanırsın. Eline, Tüketme özelliğine sahip 2 adet \"Koruma Darbesi\" kopyası yerleştir."
  },
  Skill_4334_tempOverLimitUtlSkillDesc_3 = {
    Text = "<Block:[Block:Arg1]> Kalkan kazan. <PainWord:Tahammül> yığınlarının [Arg2]%'si ([Arg3]) kadar Can yenile ve <PainWord:Tahammül> yığınlarının yarısını kaldır. Alınan her Saldırı için saldırgana 1 tur süren [Poison:Arg4] yığın <IntoxicationIconKeywords:Zehir> uygula. Bu savaş için Tahammül sınırı %100 artırılır ve Maksimum can kadar Tahammül kazan. Ele Tükenme özellikli 2 \"Koruma Darbesi\" ekle. Bu turda alınan her Saldırı, bir sonraki \"Koruma Darbesi\"nin <PainWord:Tahammül> tüketim Etkisini %40 artırır, en fazla 5 kez yığılır."
