  Skill_4374_Name = {Text = "Yara"},
  Skill_4375_AwakerSkillBackgroundStory = {
    Text = "Adım adım, yavaşça denize girdi.\nBaşlangıçta cildine hafif soğuk gelen gece denizi, kısa sürede bir insan kucaklaması kadar sıcak hâle geldi.\n\"Deniz beni kabul etti,\" diye düşündü Nymphaea kendi kendine.\nDalıp giderken, ebeveynlerinin gülümsemelerini gördü. Denizin derinliklerinde, mutlaka ailevi bir mutluluk olmalıydı."
  },
  Skill_4375_Desc_0 = {
    Text = "Nymphaea <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Nymphaea bir kart oynadıktan sonra <Energy:[Energy:Arg2]> Aliemus elde eder. Tur sonunda, Nymphaea'nın verdiği Zehir miktarını [Arg3]% artır."
