    Text = "Sayısız dişli birbirine kenetleniyor, birbirini harekete geçiriyor ve porselen kabuğa yaşamı taklit etme yeteneği veriyor.\nBu onun en gurur duyduğu yaratımı, kopyalanamayan karmaşık bir mekanizma.\nErica, adını taşıyan otomatonun ikinci hayatı olacağını asla hayal edemezdi."
  },
  Skill_4403_Desc_0 = {
    Text = "Erica <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Rouse>: Erica Hasar verdiğinde [Power:Arg2] Geçici <PowerIconKeywords:STR> elde eder; Erica Kalkan uyguladığında [Arg3] Geçici <AlertIconKeywords:Alert> elde eder."
  },
  Skill_4403_Desc_15 = {
    Text = "Erica <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Erica Hasar verdiğinde [Power:Arg2] Geçici <PowerIconKeywords:GÜÇ> kazanır; Erica Kalkan uyguladığında [Arg3] Geçici <AlertIconKeywords:Alarm> kazanır. Erica Taşkınlık serbest bıraktıktan sonra, Taşkınlığı ek olarak 1x GÜÇ ve Alarm bonuslarından yararlanır."
  },
