  Skill_4407_AwakerSkillBackgroundStory = {
    Text = "Cildi yeşile dönmüş ve çürüyen damarlar durmaksızın kıvrılıp bükülüyor.\nOmzunda bir şey büyüyor gibi görünüyor—siyah bir sıvı kolundan aşağı sızarak ameliyat masasına yayılıyor.\nYaradan yeni doğmuş et fışkırıyor, istekli ve nazik, sessizce.\nSemptom: Zayıflık taşıyan kız gülümsüyor.\n\"Tekrar görüşüyoruz, @2.\""
  },
  Skill_4407_Desc_0 = {
    Text = "Rastgele olarak [Arg2] kez <Damage:[Damage:Arg1]> Hasar ver. Sonraki turun başında, kaybedilen her 2 Can için 1 Kalkan kazan."
  },
  Skill_4407_Desc_1 = {
    Text = "Rastgele olarak [Arg2] kez <Damage:[Damage:Arg1]> <PunctureDamagewords:Pierce DMG> ver. Bir sonraki turun başına dek, bir sonraki turun başında kaybedilen her 2 HP için 1 Kalkan kazan."
