  Skill_4408_AwakerSkillBackgroundStory = {
    Text = "Bilinen insan spektrumunda böyle bir ışık yoktur.\nBir kutup ışığı gibi parıldar, bir kutup ışığı gibi uzaktır ve bir kutup ışığı gibi gelip geçicidir."
  },
  Skill_4408_Desc_0 = {
    Text = "[Power:Arg1] <PowerIconKeywords:STR> elde et. Geçici Kritik Oranı +[Arg2]%. Bu Savaş boyunca, Tinct’in Darbe Temel Hasarı [Arg3]% artar. Elde rastgele 5 kart seç ve turların sonuna kadar Arithmetica Maliyetlerini 1 azalt."
  },
  Skill_4408_Desc_3 = {
    Text = "[Power:Arg1] <PowerIconKeywords:STR> elde et. Geçici Kritik Oranı ve Krit. Hasar +[Arg2]%. Bu Savaş süresince, Tinct’in \"Darbe\" Temel Hasarı [Arg3]% artar. Elde bulunan rastgele 5 kartın Arithmetica Maliyetini turun sonuna kadar 1 azalt."
  },
  Skill_4408_EffectNameList_0 = {Text = "Güç"},
  Skill_4408_Name = {
