  Skill_4410_Desc = {
    Text = "<Block:[Block:Arg1]> Kalkan elde et. Kendi üzerindeki <VulnerabilityIconKeywords:Savunmasız> durumunu dağıt. Çekme Desteğinden en fazla 3 kart seç ve eline ekle."
