  },
  Skill_4412_AwakerSkillBackgroundStory = {
    Text = "Aliemus’la dolup taşan \"Boyun Eğmez\" adlı kırbaç, ne zaman ve nerede olursa olsun, arzuladığın acıyı verebilen, daima parlak bir ışıltıyla yanar."
