  },
  Skill_4413_AwakerSkillBackgroundStory = {
    Text = "Askere yazıldıktan sonra ön cephelerde cesurca savaştı, engelli olduktan sonra bile geri adım atmak istemedi; çünkü \"daha iyi bir dünya\"nın geleceğine içtenlikle inanıyordu.\nAma yalanlar eninde sonunda paramparça olur. Bu sefer silahını o sahte vaat için değil, kalbindeki doğru olan şey için kaldırıyor."
  },
  Skill_4413_Desc_0 = {
    Text = "Alva <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: [Arg2] <AlertIconKeywords:Alarm> elde et. Alva'nın Komut Kartlarından gelen Hasar mevcut Kalkan ile artar; her Kalkan puanı başına 2 Hasar artar."
  },
  Skill_4413_Desc_15 = {
