  Skill_4575_AwakerSkillBackgroundStory = {
    Text = "Mercanlardan yapılmış kadim bir kalıntı.\nBaşlangıçta, denizde parıldayan yalnızca beyaz bir ışıltıydı.\nSonra yüksek basamaklar belirdi, bükülmüş kabartmalar ve yükselen sütunlarla birlikte...\nBam! Her şey aniden durduğunda, kayıp sanat sonunda suyun altında kendini gösterdi.\nSanatın olduğu yere gitmeli."
  },
  Skill_4575_BattleDesc_0 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı kazan. Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver; her 1 Karakter Kalkanı için Hasar [Arg3] artar ve fazladan [Arg4]% Krit. Oranı ve Krit. Hasar bonusundan yararlanır. Reis Savaşlarında 1 ek kez Hasar verir."
  },
  Skill_4575_BattleDesc_3 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı kazan. Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver; her 1 Karakter Kalkanı için Hasar [Arg3] artar ve fazladan [Arg4]% Krit. Oranı ve Krit. Hasar bonusundan yararlanır. Reis Savaşlarında 1 ek kez Hasar verir."
