  Skill_4575_Name = {
    Text = "Yitik Sanat"
  },
  Skill_4575_OverLimitUtlSkillDesc_0 = {
    Text = "Gain <Block:[Block:Arg5]> Karakter Kalkanı. Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver, bu Hasar her bir Karakter Kalkanı puanı için [Arg3] artar ve fazladan [Arg4]% Krit. Oranı ve Krit. Hasar bonusundan yararlanır. Reis Savaşlarında fazladan 1 kez daha Hasar verir. Bu savaş boyunca, \"Yitik Sanat\" ve \"Temel Darbe\"nin verdiği Hasar, fazladan %100 Karakter Kalkanı bonusundan yararlanır."
  },
  Skill_4575_OverLimitUtlSkillDesc_3 = {
    Text = "Gain <Block:[Block:Arg5]> Karakter Kalkanı. Tüm düşmanlara <Damage:[Damage:Arg2]> Hasar ver, bu Hasar her bir Karakter Kalkanı puanı için [Arg3] artar ve fazladan [Arg4]% Krit. Oranı ve Krit. Hasar bonusundan yararlanır. Reis Savaşlarında fazladan 1 kez daha Hasar verir. Bu savaş boyunca, \"Yitik Sanat\" ve \"Temel Darbe\"nin verdiği Hasar, fazladan %100 Karakter Kalkanı bonusundan yararlanır."
  },
  Skill_4575_PropertyNameList = {
