  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "Büyücü dedi ki: \"Çok sayıda kâfir var.\nBiz Levant'ta çok zayıf görünüyoruz.\nKardeş Uvhash, borazanını çal,\nve bir deli gibi savaş.\"\nSavaşçı yanıtladı: \"Burada kâfir yok.\nHepiniz benim tarafımdan öldürüleceksiniz, etnik kökeniniz ya da inancınız ne olursa olsun.\nZamanı geldiğinde, cesetler vadiyi kaplayacak ve dağın zirvesini dolduracak,\nBu benim Kan ve Kum'a sunacağım haraç olacak.\""
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Devour>: Sonraki [Kan ve Kum İlahisi] Hasarı +[Arg4], bu savaş boyunca STR çarpanı +[Arg3].] Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver. Bu Hasar, ×[Arg2] <PowerIconKeywords:STR> çarpanından yararlanır. Uvhash <Energy:[Energy:Arg5]> Aliemus elde eder."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Yutma>: Bu savaşta sonraki \"Kan ve Kum İlahisi\" +[Arg4] Hasar ve [Arg3]x STR çarpanı uygular.] Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar verir. <PowerIconKeywords:STR>, \"Kan ve Kum İlahisi\" üzerinde [Arg2]x etki uygular. Uvhash'ın Aliemus Yenilenmesinin 2 katına eşit Aliemus kazan."
  },
  Skill_4579_EffectNameList = {
    Text = "Hasar,Hasar▲"
  },
  Skill_4579_Name = {
    Text = "Kan ve Kum İlahisi"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Devour>: Bu savaşta sonraki \"Kan ve Kum İlahisi\"nin Hasarı [Arg4] puan artar ve Güç çarpanı [Arg3] kat yükselir.] Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver. <PowerIconKeywords:STR>, \"Kan ve Kum İlahisi\"ni [Arg2] kat güçlendirir. Uvhash <Energy:[Energy:Arg5]> Aliemus elde eder. Elini, Tüketme ve Geçici özellikli \"Çığlık At, Kan!\" kartlarıyla doldur. Bu tur Uvhash'in hasar isabet sayısını 1 artır."
  },
  Skill_4579_PropertyNameList = {
