  Skill_4581_AwakerSkillBackgroundStory = {
    Text = "Kilise'nin altında gizli bir alan bulunur.\n\nPiskopos Tablet'in önünde diz çöker, yaratılışın şafağından aktarılan gizli kelimeleri okur.\n\nZamanın unuttuğu runlar karşılık veren bir parıltı yayar, piskoposun iradesiyle devasa bir hayalet tezahür ettirir ve ışığında yıkananları \"Kutsama\" ile ödüllendirir."
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devour>: [Power:Arg1] Geçici <PowerIconKeywords:STR> kazan, +[Arg4]% Geçici Kritik Oranı.] <Block:[Block:Arg2]> Kalkan kazan. Tüm düşmanları 1 tur boyunca <VulnerabilityIconKeywords:Vulnerable> yap. Bir sonraki turun başına kadar alınan Hasarın [Arg3]%'i Kızıl Ocak İyileştirmesine dönüştürülür."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:Yutma>: [Power:Arg1] Geçici <PowerIconKeywords:GÜÇ> elde et, Geçici Kritik Oranı +[Arg4]%.] <Block:[Block:Arg2]> Kalkan elde et. Tüm düşmanlara 1 tur boyunca <VulnerabilityIconKeywords:Savunmasız> uygula. Bir sonraki turun başına kadar, saldırıya uğradığında, alınan Hasarın [Arg3]%'i Kızıl Ocak İyileştirmesine dönüştürülür. Salvador [Arg5]% Geçici Kritik Hasar elde eder."
  },
