  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "Faint eksiktir.\nFaint tehlikelidir.\nFaint lanetlidir.\nYıldızlardan gelen Faint, en tuhaf ve en canlı renktir."
  },
  Skill_4615_BattleDesc_15 = {
    Text = "Faint <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Tüm düşmanlardan anında ve kalıcı olarak [Arg4] <PowerIconKeywords:STR> <TouquKeywords:Çal>. [Counterattack:Arg3] yığın <RetaliateIconKeywords:Karşı Atak> kazan. Bu savaş için Direnç azalma hızı %50'den %45'e düşürülür. Faint bir kart oynadığında, tüm düşmanlardan [Arg2] <PowerIconKeywords:STR> <TouquKeywords:Çal>. Tur sonunda, Faint'in <RetaliateIconKeywords:Karşı Atak> değerinin %50'si kadar <RealDamage:Sabit Hasar> ver."
  },
  Skill_4615_Desc_0 = {
    Text = "Faint, <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: [Counterattack:Arg3] yığın <RetaliateIconKeywords:Karşı Atak> kazan. Bu savaş boyunca Direnç bozunma hızı %50'den %45'e düşürülür. Faint bir kart oynadığında, tüm düşmanlardan [Arg2] <PowerIconKeywords:Güç> <TouquKeywords:Çal>. Tur sonunda, Faint'in <RetaliateIconKeywords:Karşı Atak> değerinin %50'si kadar <RealDamage:Sabit Hasar> ver."
