  Skill_4617_AwakerSkillBackgroundStory = {
    Text = "Denizcilerin çaresiz çığlıkları arasında, sessizce izliyor ve bekliyor.\nDurgun deniz yüzeyinden kabarcıklar yükseliyor ve devasa bir Dokunaç belirerek hızla direğe sarılıyor ve deniz esintisinde yepyeni bir yelken gibi açılıyor.\n\"Yelken aç, yelken aç!\" diye şarkı söylüyor denizciler, \"Hayalin içinde yola çıkıyoruz!\""
  },
  Skill_4617_Desc = {
    Text = "<Heal:[Heal:Arg1]> HP iyileştir. Geçici <TentacleInjurieIconKeywords:Dokunaç Hasarı> +[TentaclePower:Arg2]. Tüm düşmanlara 1 tur boyunca <WeaknessIconKeywords:Zayıflık> uygula. Düşmanlara saldırması için 1 Dokunaç tetikle, [Arg3]% Dokunaç Hasarı verir."
