  },
  Skill_4654_Desc = {
    Text = "[Arg1] Karakter Kalkanı kazan. Lily’nin çağırdığı balçık Karakter Kalkanı, sadece ve sadece bir Cehennem Köpeği’nin Yırtış’ına dayanabilir. Gerçekten... acıtmayacak mı?"
  },
  Skill_4654_Name = {
    Text = "Balçık Üzerinde Ölümsüz Çiçek"
  },
  Skill_4655_AwakerSkillBackgroundStory = {
    Text = "\nOkyanus derin ve sakindir; yaşam arzusunu ve ölüm korkusunu taşır.\nYine de, okyanusu kahkaha ve yaramazlıkla doldurmayı seçenler vardır—Aurita böyle bir davet uzattığında, insanın aklına hep “neden onunla biraz eğlenmeyeyim ki” düşüncesi gelir ve basit bir sevinç kalbi doldurur."
  },
  Skill_4655_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver. Çekme Destesi ve Atılmış Kart Destesi’nden en fazla 10 \"Bez Bölünmesi\" harca; her biri 1 ek Hasar örneği sağlar. Ele 2 \"Bez Bölünmesi\" al. Bu savaşta Aurita’nın Hasar çıktısını [Arg2] artır."
  },
  Skill_4655_Desc_2 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:Delici Hasar> ver. Çekme destesinden ve Atılmış Kart Deste­sinden en fazla 10 adet \"Bez Bölünmesi\" kartı tüket; her biri fazladan bir Hasar örneğine neden olur. Eline 2 adet \"Bez Bölünmesi\" kartı yerleştir. Bu savaşta Aurita’nın verdiği Hasarı [Arg2] puan artır."
  },
  Skill_4655_EffectNameList = {
    Text = "Hasar,Takip Hasarı▲"
  },
  Skill_4655_Name = {
    Text = "Gürültülü Okyanus"
  },
  Skill_4655_OverLimitUtlSkillDesc_0 = {
    Text = "<Damage:[Damage:Arg1]> puan Hasar verir. Çekme Destesi ve Atılmış Kart Destesi'ndeki en fazla 10 adet \"Bez Bölünmesi\" kartını tüketir, her kart için 1 kez ek Hasar verir. 2 adet \"Bez Bölünmesi\" kartını Ele alır. \"Aurita\"nın bu savaşta sonraki verdiği Hasarı [Arg2] puan artırır. [Power:Arg2] puan <PowerIconKeywords:Güç> ve [TentaclePower:Arg2] puan <TentacleInjurieIconKeywords:Dokunaç Hasarı> kazanır; sonraki 5 \"Bez Bölünmesi\" oynadığında her seferinde 1 kart çekilir."
  },
  Skill_4655_OverLimitUtlSkillDesc_2 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:Delme Hasarı> ver.\nÇekme destesinden ve Atılmış Kart Desteği’nden en fazla 10 “Bez Bölünmesi” kartı tüket; her biri fazladan 1 hasar örneği ekler.\nEline 2 “Bez Bölünmesi” kartı koy.\nBu Savaşta Aurita’nın sonraki Hasarını [Arg2] puan artır.\n[Power:Arg2] <PowerIconKeywords:STR> ve [TentaclePower:Arg2] <TentacleInjurieIconKeywords:Tentacle Hasarı> kazan ve “Bez Bölünmesi”ni oynadığın sonraki 5 seferin her birinde 1 kart çek."
  },
