  Skill_4658_AwakerSkillBackgroundStory = {
    Text = "Casiah'ın elleri boş;\nCasiah'ın şapkası boş;\nCasiah'ın göğsü boş.\nBoş Casiah, neşesiz bir şenlikte boş bir gösteri sergiliyor."
  },
  Skill_4658_Desc_0 = {
    Text = "Casiah <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Casiah oynanan her kart için [Power:Arg2] Geçici <PowerIconKeywords:GÜÇ> kazanır."
