  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Bir, iki... bir, iki...\nHafif bir ritimle kalabalığın arasından süzülerek tepsiyi taşıdı.\nKonuklar durmaksızın içip şarkı söylüyordu; o da durmaksızın servis yapıp gülümsüyordu.\nBurada her şey altındı. Altın bir salon, altın şarap ve altın elbiseler.\nKaren altına bayılırdı. İyice prova ettiği imza gülümsemesini takındı.\n\"Afiyet olsun, değerli konuğum—!!\""
  },
  Skill_4660_Desc_0 = {
