  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "İnsanlar onun güzelliğine hayran kaldı ve çekiciliğini kıskandı, ama kimse tomurcuklanan bir çiçeğe dikkat etmedi.\nÇorak arazide belirsizce sallanarak, başkalarının insafına kalmış, bahçıvanın yükselişi için bir pazarlık kozu olarak kullanılmıştı.\nAncak tacın önünde çiçek açtığında insanlar delinip kanadıklarını fark ettiler."
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Rastgele <Damage:[Damage:Arg1]> Hasarı [Arg3] kez ver. Tur sonunda <Heal:[Heal:Arg2]> HP yenile."
