  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "Soğuk makine kalbin yerini aldı ve hidrolik yağ borulardaki kanın yerini aldı. Soğuk, rasyonel olmalı ve talimatlara göre hareket etmeliydi.\nAma kabuğunun içinde dışarıdan gelen bir irade sessizce kıpırdandı. Kana ihtiyacı yoktu, sıcaklığa ihtiyacı yoktu; insanlık dışı bir kötülükle kendi başına yanabilirdi. Dedi ki: Boyun eğ, seni aşağılık ve önemsiz yaratık, sonra kavurucu elektrik küremde yok ol."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "[Power:Arg1] Geçici <PowerIconKeywords:GÜÇ> elde et. <Posse:[Arg2]> Keyflare elde et. Kendi <WeaknessIconKeywords:Zayıflık> durumunu dağıt. Bir kart <DimensionalSpaceIconKeywords:Ultra Uzay>a her girdiğinde, <DerivativeCardKeywords_14:\"Toplama: Meka\">ya dönüş."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "[Power:Arg1] Geçici <PowerIconKeywords:STR> elde et. <Posse:[Arg2]> Anahtar Alevi elde et. Kendi üzerindeki <WeaknessIconKeywords:Weakness> durumunu dağıt. Erica’dan 1 \"Darbe\" <DepleteIconKeywords:Tüketme> eline ekle. Bir kart <DimensionalSpaceIconKeywords:Ultra Uzay>a girdiğinde, <DerivativeCardKeywords_14:\"Geri Çek: Meka\">ya dönüş."
  },
  Skill_4663_Desc_0 = {
    Text = "[Power:Arg1] Geçici <PowerIconKeywords:GÜÇ> elde et. Erica'nın Keyflare Yenilenmesine eşit Keyflare elde et. Kendi<WeaknessIconKeywords:Zayıflık> durumunu dağıt. 1 kart <DimensionalSpaceIconKeywords:Ultra Uzay>a her girdiğinde, <DerivativeCardKeywords_14:\"Toplama: Meka\">ya dönüş."
  },
  Skill_4663_Desc_1 = {
    Text = "[Power:Arg1] Geçici <PowerIconKeywords:STR> elde et. Erica’nın Anahtar Alevi Yenilenmesine eşit miktarda Anahtar Alevi elde et. Kendi üzerindeki <WeaknessIconKeywords:Weakness> durumunu dağıt. Eline Erica tarafından eklenmiş, üzerinde <DepleteIconKeywords:Tüketme> bulunan 1 \"Darbe\" ekle. Bir kart <DimensionalSpaceIconKeywords:Ultra Uzay>a girdiğinde, <DerivativeCardKeywords_14:\"Geri Çek: Meka\">ya dönüş."
  },
