  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "Görünmez bir veba sessizce sonsuz acı ve çılgınlık getiriyor.\n\nPiskopos geceleri uyuyamıyor, insanların acısını hafifletememekten derin ızdırap çekiyor.\n\n\"Ey Merhametli Yaratıcı, onları kurtar. Tüm acılarını ve kederlerini taşımaya razıyım.\"\n\nBöylece Ulu Peder ona \"Kutsama\" bahşetti ve Kutsal Yazıt işlenmiş Tablet'i kullanarak yardım işleri yapmasına izin verdi."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador <Energy:[Energy:Arg1]> çılgınlık puanı kazandı. <ExaltIconKeywords:Gnosis Uyanışı>: Eline 1 adet <B02AFKeyWord:Aşk Korumaktır> kartı koy. Tur sonunda [Power:Arg2] puan <PowerIconKeywords:Güç> kazan."
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Ele 1 <B02AFKeyWord:Aşk Korumaktır> yerleştir. Tur sonunda [Power:Arg2] <PowerIconKeywords:GÜÇ> kazan. \"Koruyucu Olan\" ve \"Kutsanmış Kemikler\" tarafından biriktirilen Kızıl Ocak +%25 artar ve \"Acının Sonu\" için \"Kurtuluş\" seçildiğinde, Kızıl Ocak'tan tüketilen her %1 Maksimum can +%5 Final Hasar verir."
  },
