  Skill_4667_AwakerSkillBackgroundStory = {
    Text = "Tüm boyutları aşan devasa bir Labirent.\nLabirent'e giren yolcular kaba bir pazarlıkla yüzleşmek zorundadır.\n\"Hayır\" derseniz, sonsuza dek Labirent'te mahsur kalırsınız.\n\"Evet\" derseniz, size küfür dolu bir döl yerleştirilir ve tüm anılarınız silinir.\nNe mi? İşlemin ayrıntılarını mı soruyorsunuz?\nLabirent'in solgun Efendisi dahil kimse işlemin ayrıntılarını bilmiyor.\nBir pazarlık sadece bir pazarlıktır."
  },
  Skill_4667_Desc_0 = {
    Text = "[<DevouredIconKeywords:Yutma>: [Power:Arg1] <PowerIconKeywords:GÜÇ> ve [Arg4] <AlertIconKeywords:Alarm> elde et.] <Block:[Block:Arg2]> Karakter Kalkanı elde et. Tüm düşmanlara [Poison:Arg3] yığın <IntoxicationIconKeywords:Zehir> uygula."
  },
  Skill_4667_EffectNameList = {
    Text = "GÜÇ,Alarm,Karakter Kalkanı,Zehir"
