  Skill_4667_Name = {
    Text = "Solgun Kutsama"
  },
  Skill_4667_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devour>: [Power:Arg1] <PowerIconKeywords:STR> ve [Arg4] <AlertIconKeywords:Alert> elde et.] <Block:[Block:Arg2]> Kalkan elde et. Tüm düşmanlara [Poison:Arg3] yığın <IntoxicationIconKeywords:Poison> yükle. Agrippa'nın Darbe olmayan 2 SAVUNMA Komut Kartını çek ve bu tur için eldeki Agrippa'ya ait Darbe olmayan 2 SAVUNMA Komut Kartının Arithmetica Maliyetini 1 azalt."
  },
