  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "Loş New Gate Hapishanesi'nde, Londinium'da her yerde bulunan balmumu yağı bile nadir bir lükstür.\nNadir olduğu için önemli anlara saklanır; örneğin cezalandırma için ve yaramaz çocukların cildine uygulanır.\nÖzel bir balmumu yağı olmasa da, damlaması acıklı çığlıklarla birlikte gelir. Ancak bir kızın kulaklarına zarif bir şiir gibi gelir."
  },
  Skill_4694_BattleDesc_0 = {
    Text = "[Counterattack:Arg2] yığın <RetaliateIconKeywords:Sayaç> kazan. Tüm düşmanların <ExhaustionIconKeywords:GÜÇ> değerini [Exhaustion:Arg1] kadar geçici olarak azalt, her düşman için [Power:Arg1] Geçici <PowerIconKeywords:GÜÇ> kazan. Tüm düşmanların <RetaliateIconKeywords:Sayaç> değerini kaldır."
