  Skill_4703_AwakerSkillBackgroundStory = {
    Text = "Efendiyi koru. Efendiyi koru. Efendiyi koru.\nYaralarla kaplı olsa bile, emir sonuna kadar yerine getirilmeli.\nDüşman güçlü, o hâlde yasak bölgeyi daha da genişlet. Beden acı içinde, ama bu emrin yerine getirilmesini engellemez."
  },
  Skill_4703_BattleDesc_0 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et ve tüm düşmanlara [Poison:Arg2] yığın <IntoxicationIconKeywords:Poison> uygula. Bir sonraki turun başlangıcına kadar, alınan her saldırı için [Arg3] yığın <PainWord:Endure> kazan."
  },
  Skill_4703_BattleDesc_1 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et ve tüm düşmanlara [Poison:Arg2] yığın <IntoxicationIconKeywords:Zehir> uygula. Bir dahaki turun başlangıcına kadar, alınan her saldırı için [Arg3] yığın <PainWord:Tahammül> kazan. CP %50’nin altındaysa ([Arg4]), ek bir Karakter Kalkanı kazan ve uygulanan Zehri ikiye katla."
  },
  Skill_4703_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et ve tüm düşmanlara [Poison:Arg2] yığın <IntoxicationIconKeywords:Poison> uygula. Lily’nin sahip olduğu her 1% Ölüm Direnci için Temel Karakter Kalkanı %0,25 artar. Bir sonraki turun başlangıcına kadar, alınan her saldırı için [Arg3] yığın <PainWord:Endure> kazan."
  },
  Skill_4703_Desc_1 = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı elde et ve tüm düşmanlara [Poison:Arg2] yığın <IntoxicationIconKeywords:Zehir> uygula. Lily’nin her %1 Ölüm Direnci için, Temel Karakter Kalkanı %0,25 artar. Bir dahaki turun başlangıcına kadar, alınan her saldırı için [Arg3] yığın <PainWord:Tahammül> kazan. CP %50’nin altındaysa, ek bir Karakter Kalkanı kazan ve uygulanan Zehir ikiye katlanır."
