  Skill_4729_AwakerSkillBackgroundStory = {
    Text = "\n\"Evet, bir zamanlar ona böyle bir söz verdim.\"\nAnavatanın çöküş gününden bahsederken, genç kralın ifadesi giderek daha yorgun bir hâl aldı.\n\"Sadece o sözlerin ölümden önceki korkusunu teselli etmesini ummuştum; onları bir rehber ilke olarak benimseyeceğini hiç hayal etmemiştim...\""
  },
  Skill_4729_Desc_0 = {
    Text = "Kendindeki <WeaknessIconKeywords:Zayıflık> Durumunu dağıt.\n[TentaclePower:Arg1] Geçici <TentacleInjurieIconKeywords:Tentacle Hasarı> ve [Power:Arg1] Geçici <PowerIconKeywords:STR> elde et.\nMevcut Duruş \"Sakin Deniz\" ise, bu tur tüm düşmanların <ExhaustionIconKeywords:STR> değerini ayrıca [Exhaustion:Arg3] azalt.\n<RippleKeywords:Artçı Sarsıntı>: 1 Dokunaç’a saldırı emri ver."
  },
  Skill_4729_Desc_3 = {
    Text = "Kendindeki <WeaknessIconKeywords:Zayıflık> Durumunu dağıt.\n[TentaclePower:Arg1] Geçici <TentacleInjurieIconKeywords:Tentacle Hasarı> ve [Power:Arg1] Geçici <PowerIconKeywords:STR> elde et.\n[Arg2]% Geçici Kritik Oranı elde et.\nMevcut Duruş \"Sakin Deniz\" ise, bu tur tüm düşmanların <ExhaustionIconKeywords:STR> değerini ayrıca [Exhaustion:Arg3] azalt.\n<RippleKeywords:Artçı Sarsıntı>: 1 Dokunaç’a saldırı emri ver."
