  Skill_4748_AwakerSkillBackgroundStory = {
    Text = "Çocuklar, masalların özünü yavaş yavaş görmeye ve mitlerin ardındaki kıssaları anlamaya başlar. İnsan dilinde bu sürece “büyümek” denir.\nAma bazı Çocuklar, iyi geceler masallarına gitgide daha çok inanır; gökyüzünde gerçekten gökkuşağı köprüleri ve Derin Deniz’in altında batmış uygarlıklar olduğuna inatla kafa yorarlar.\nAurita bu hikâyeleri sever ve bu sevinci daha çok arkadaşıyla paylaşmak ister."
  },
  Skill_4748_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:Dokunaç Hasarı> +[TentaclePower:Arg1]. Elde kalan tüm kartları at, ardından aynı sayıda kart çek. Atılmış Kart Destesi'ne 1 \"Bez Bölünmesi\" karıştır."
  },
  Skill_4748_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:Dokunaç Hasarı> +[TentaclePower:Arg1]. Elde kalan tüm kartları at, ardından aynı sayıda +1 kart çek. Atılmış Kart Destesi'ne 1 \"Bez Bölünmesi\" karıştır."
