  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Besle, doğ, çoğal.\nYavaşça çözülen gerçeklikte, kararan dünyada, doğmak üzere olan boşlukta.\nSenin varlığın Ananın fedakârlığının meyvesi ve Ananın sürekliliğinin sebebidir.\nKutsal çocuklar, yeni dünyada yeniden doğun—o saf, korkunun yok edildiği yeni dünyada yeniden doğun."
  },
  Skill_4750_Desc_0 = {
    Text = "Thais <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Hemen 1 <DerivativeCardKeywords_10:Kutsal Çocuk> kartı kazan. Her Müfreze kullandığında, eldeki bir Embriyo'yu <DerivativeCardKeywords_10:Kutsal Çocuk>'a dönüştür."
  },
  Skill_4750_Desc_15 = {
    Text = "Thais <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Hemen 1 <DerivativeCardKeywords_10:Saflığın Varisi> kazan. Her Müfreze serbest bırakıldığında, eldeki 1 Embriyo'yu 1 <DerivativeCardKeywords_10:Saflığın Varisi>'ne dönüştür. \"Bereket Ritüeli\" ek olarak eline 1 ekstra kopya yerleştirir."
  },
