  Skill_4759_AwakerSkillBackgroundStory = {
    Text = "Dünyada özel bir tür denizanası vardır. Yaralandıktan sonra, kopmuş dokuları yeniden büyüyerek bütünüyle yeni bir hidroid bedene dönüşebilir.\n“Aurita da denizanası üretebiliyor! O hâlde Aurita da bir denizanası!”\nBir çocuğun dünyanın işleyişini bu aşamada kavrayışı karşısında, hevesini kırmamak en iyisidir."
  },
  Skill_4759_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver. Atılmış Kart Destesi’ne [Arg2] adet \"Bez Bölünmesi\" karıştır. <RippleKeywords:Aftershock>: <Energy:[Energy:Arg3]> Aliemus kazan."
