  Skill_4760_AwakerSkillBackgroundStory = {
    Text = "Aigis'in bebeklerinin baktığı nesneler, bakış noktasından itibaren renklenerek lifleşmeye başlar. Zamanla, bu alan renkli ipliklere benzeyen bir maddeye dönüşebilir ve bebekler tarafından emilir. Bakış zamanında engellenmezse, nesne tamamen çözülebilir ve bebeğin bir parçası haline gelebilir.\n\nSadece Aigis'in kendisinin bebeklerin bakışından etkilenmediği gözlemlenmiştir."
  },
  Skill_4760_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver; bu Hasar 2x GÜÇ bonusundan yararlanır. Hedef <VulnerabilityIconKeywords:Savunmasız> ise, kartın Arithmetica Maliyetini iade et ve 1 kart çek."
