  Skill_4769_Desc_0 = {
    Text = "<Block:[Block:Arg1]> Kalkan ve [Counterattack:Arg2] yığın <RetaliateIconKeywords:Counter> elde et. Bu tur atılacak bir sonraki Sıçrama’nın tetiklenmesi garanti edilir. <DreamGuide:Düş Yemi> yığınlarını tüketmeyi seçerek <JingjinvwangKeywords1:Derin Uyku Karşı Saldırısı> ya da <JingjinvwangKeywords2:Mırıltı Yankıları>nı tetikle. Eğer <DreamGuide:Düş Yemi> yığınlarının sayısı 5’ten azsa, 1 yığın <DreamGuide:Düş Yemi> elde et."
  },
