  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "Alevler yayıldı, tiyatronun tavanını zümrüt yeşiline boyadı; tıpkı sabah gölünün dingin ve berrak suları gibi.\nNicesi bu zümrüt silüetin peşinden geldi, oysa diğerleri akıcı ve güçlü dansı görmezden gelip yalnızca hafifçe görünen beyaz kolları ve eteğin altında hayal ettikleri sahneleri gördü.\nAma dansçı sadece orada duruyordu, sanki donmuş gibi, yeşil alevlerin yuttuğu ölüme yakın bir duruşla."
  },
  Skill_4804_Desc_0 = {
    Text = "Liz <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Liz'in verdiği her [Arg2] <plural value=\"[Arg2]\" singular=\"Hasar örneği\" plural=\"Hasar örneği\"> için <DepleteIconKeywords:Tükenme> özellikli bir <DerivativeCardKeywords_18:\"Yeşil Alevler\"> ele ekle, tur başına en fazla 3 kez."
  },
  Skill_4804_Desc_15 = {
    Text = "Liz <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Liz'in verdiği her [Arg2] <plural value=\"[Arg2]\" singular=\"Hasar örneği\" plural=\"Hasar örneği\"> için <DepleteIconKeywords:Tükenme> özellikli 1 <DerivativeCardKeywords_18:\"Yeşil Alevler\"> ele ekle, tur başına en fazla 3 kez. Bu savaşta Liz'in verdiği Hasar, her 3 Hasar örneği için +[Arg3] artar."
