  Skill_4821_AwakerSkillBackgroundStory = {
    Text = "Labirenti dünyanın her köşesine uzanır.\nSık ormanlarda, kütüphanelerin altında ve denizin dibinde girişler vardır.\nLabirente giren o talihsiz ruhlara dayanarak, dünyayı ancak kabataslak çizebilir.\nYolcular sürekli kıvrılan koridorlarda kaybolurken, o sürekli değişen hikayelerde kaybolur.\nHer şeyi bilir, ama labirentten asla ayrılamaz."
  },
  Skill_4821_Desc_0 = {
