  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "Sonsuz gezinmeler içinde Tinktur, evinin adını çoktan unuttu.\nZamanın uzun akışında, kozmos o ölü gezegenin adını unuttu.\nBu gezegenler topluca \"ıssız gezegenler\" olarak anılır, tıpkı sayısız çözülmüş ve terk edilmiş gezegen gibi.\nOnun şarkısı, o dış dünya gezegeninin son yankısı olabilir."
  },
  Skill_4822_Desc_0 = {
