  Skill_4824_AwakerSkillBackgroundStory = {
    Text = "Liz, Yeşil Alevler'i elde ettiği günü hâlâ hatırlıyor.\nCamgöbeği kıvılcım avucunda dans ederek, onu uzun süredir bastırdığı dileğini gerçekleştirmeye çağırıyordu."
  },
  Skill_4824_Desc_0 = {
    Text = "Rastgele bir düşmana <Damage:[Damage:Arg2]> <PunctureDamagewords:Delici Hasar> [Arg1] kez ver ve [Arg3]% Hasar ile <IntoxicationIconKeywords:Zehir> uygula. Arithmetica yetersizse zorla oynanabilir ve etkisi, oynandıktan sonra <Energy:[Energy:Arg4]> Aliemus kazanmak ve Tüketme olarak değişir."
  },
  Skill_4824_Desc_1 = {
    Text = "Rastgele bir düşmana <Damage:[Damage:Arg2]> <PunctureDamagewords:Delici Hasar> [Arg1] kez ver ve [Arg3]% Hasar <IntoxicationIconKeywords:Zehir> uygula. Tur sonunda, elde veya <DimensionalSpaceIconKeywords:Ultra Uzay> içindeyse, \"<DerivativeCardKeywords_20:Ölümcül Alevler>\"e yükselt. Yetersiz Arithmetica ile de oynanabilir; bu durumda etkisi, <Energy:[Energy:Arg4]> Aliemus elde etmek ve Tüketme olarak değişir."
  },
