  Skill_4840_AwakerSkillBackgroundStory = {
    Text = "Bu benim doğuştan gelen hakkım, Lemurya Tahtı'nın son armağanı.\n\nŞimdi yargınla yüzleş, çürümüş olan: Tersine Dönen Girdap seni talep ediyor."
  },
  Skill_4840_BattleDesc_0 = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver, [Arg4]% <TentacleInjurieIconKeywords:Dokunaç Hasarı> bonusundan yararlanır. [Arg2] tur boyunca <WeaknessIconKeywords:Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygula. [Arg3]% <SacrificeKeyWord:Kurban> yığınını kaldır."
  },
  Skill_4840_BattleDesc_1 = {
    Text = "Tüm düşmanlara [Arg5] kez <Damage:[Damage:Arg1]> Hasar ver.\nHer 2 Dokunaç için fazladan 1 kez daha Hasar ver; bu Hasar, [Arg4]% <TentacleInjurieIconKeywords:Tentacle Hasarı> bonusundan yararlanır.\n[Arg2] tur boyunca <WeaknessIconKeywords:Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygula.\n[Arg3]% <SacrificeKeyWord:Kurban> yığınını kaldır."
  },
  Skill_4840_Desc_0 = {
    Text = "Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver, [Arg4]% <TentacleInjurieIconKeywords:Dokunaç Hasarı> bonusuna sahiptir. [Arg2] tur boyunca <WeaknessIconKeywords:Zayıflık> ve <VulnerabilityIconKeywords:Savunmasız> uygula. [Arg3]% <SacrificeKeyWord:Kurban> yığınını kaldır."
