  Skill_4842_AwakerSkillBackgroundStory = {
    Text = "Boyutlar arası geçiş yapan cadı, boyutlar içindeki kırılma yasalarına hakimdir.\nBoyutun içindeki her yolu ve her bağlantı noktasını bilir.\nZihninde sonsuz sayıda geçit haritalanmıştır.\nBu sayede, diğer boyutlardan yansıtılan malzemeler doğal olarak onun eline geçer."
  },
  Skill_4842_Desc_0 = {
    Text = "Nergis <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Nergis'in kartı <DimensionalSpaceIconKeywords:Ultra Uzay>'a her girdiğinde, ele 1 <DerivativeCardKeywords_4:\"Kavrayış\"> yerleştir, tur başına en fazla 2 kez."
  },
  Skill_4842_Desc_15 = {
    Text = "Nergis <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Nergis'in kartı <DimensionalSpaceIconKeywords:Ultra Uzay>'a her girdiğinde, ele 1 <DerivativeCardKeywords_4:\"Kavrayış\"> yerleştir, tur başına en fazla 2 kez. 0 Arithmetica Maliyetli 1 Geçici \"Boyun Kesme\" oluştur ve Ultra Uzay'a yerleştir."
