  Skill_4845_BattleDesc_0 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:Delici Hasar> ver ve eşit miktarda <IntoxicationIconKeywords:Zehir> uygula. <O07CardKeyWord:Ritüel>: [Power:Arg3]/[Power:Arg4]/[Power:Arg5] <PowerIconKeywords:STR> ve [TentaclePower:Arg3]/[TentaclePower:Arg4]/[TentaclePower:Arg5] <TentacleInjurieIconKeywords:Dokunaç Hasarı> kazan."
