  Skill_4856_AwakerSkillBackgroundStory = {
    Text = "Avludaki çınar ağaçları hışırdadı, kuşlar bahar ilahileri söyledi ve açan güllerin kokusu tavan penceresinin dar parmaklıklarından süzülerek burnuna ulaştı.\nTenha çiçek evinde, açan her çiçek bir mezmurdu."
  },
  Skill_4856_Desc_0 = {
    Text = "<Heal:[Heal:Arg1]> HP yenile, [Power:Arg2] <PowerIconKeywords:Güç> elde et. Diğer Uyanışçılar <Energy:[Energy:Arg3]> Aliemus kazanır. Tüm Uyanışçıların Geçici Kritik Oranı ve Krit. Hasarı +[Arg4]%. Horla şu anda bir duygu durumundaysa, bu duygu durumuna karşılık gelen Görkemli Bölümler’in sağladığı etkiyi %150 artır."
