  Skill_4858_AwakerSkillBackgroundStory = {
    Text = "Kız, iflas etmiş akvaryumdan isteksizce ayrıldı ve ödeme olarak birkaç denizanasını eve götürmesine izin verildi.\nOnlar, onun en sevdiği minik yaratıklardı; denizin eterik Ruh’ları, sonsuz yaşamın çiçekleriydi.\nİyi bakılırsa tüm tankı dolduracaklardı!— Bir zamanlar böyle bir manzaranın hayalini kurmuştu."
  },
  Skill_4858_Desc_0 = {
    Text = "Aurita <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Rouse>: 1 Dokunaç elde et ve eline 2 adet \"Bez Bölünmesi\" ekle. Aurita hasar verdiğinde, [Arg2] Dokunaç bir kez saldırı yapsın."
  },
  Skill_4858_Desc_15 = {
