  Skill_59476_AwakerSkillBackgroundStory = {
    Text = "Bu ezgiyi duymadan önce, aslında dinleyecek kulaklara hiç sahip değildin. Onu duyduktan sonra ise, bir daha asla böyle sesler bulamayacaksın. Öyleyse kendini bırak, nefesini tut ve bu biricik, ömürde bir kez duyulacak melodiyi yücelt!"
  },
  Skill_59476_Desc_0 = {
    Text = "Hameln <Energy:<Energy:[Energy:Arg1]>> Aliemus elde eder.<ExaltIconKeywords:<ExaltIconKeywords:Uyanış>>: Tur başında, ele bir \"<DerivativeCardKeywords_64:<DerivativeCardKeywords_64:Uyum Senfonisi>>\" koy.<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_Desc_15 = {
    Text = "Hameln <Energy:<Energy:[Energy:Arg1]>> Aliemus kazanır. <ExaltIconKeywords:<ExaltIconKeywords:Uyanış>>: Tur başında, ele 1 \"<DerivativeCardKeywords_64:<DerivativeCardKeywords_64:Uyum Senfonisi>>\" koy. Tur başında, \"Melodi\" içeren her Kart için Hameln <Energy:<Energy:[Energy:Arg2]>> Aliemus kazanır. \"Kökenin Akordu\" serbest bırakıldığında, mevcut \"Melodi\" içeren her 2 Komut Kartı için Hasar sayısı +1<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_EffectNameList = {Text = "Aliemus"},
  Skill_59476_Name = {
    Text = "Övgüye Layık Şaheser"
  },
  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "Müzik nereden doğar? İlahi ayinlerden, çiftçilerin ilahilerinden, ilkel çığlıklardan, bahar kuşlarının cıvıltısından, çam rüzgârlarından ve okyanus dalgalarından, yerin sarsıntısından ve sıradağların çöküşünden... ya da belki de evrenin kaosundaki tanrıların fısıltılarından."
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Rastgele olarak [Arg3] kez <Damage:[Damage:Arg1]> <PunctureDamagewords:Delici Hasar> ver. Her isabet şu etkiyi uygular: Hedefin <ExhaustionIconKeywords:GÜÇ> değerini geçici olarak [Exhaustion:Arg2] azalt; [Power:Arg2] <PowerIconKeywords:Geçici GÜÇ> kazan. Elde, üzerinde <DepleteIconKeywords:Tüketme>, <HuihuanaKeywords:Rondino> ya da <XushiAKeywords:Yükselen Ezgi> bulunmayan 1 Türetilmemiş Komut Kartı seç ve ona \"<HuihuanaKeywords:Rondino>\" ekle. Eğer elinde bu koşulları sağlayan hiçbir kart yoksa, bunun yerine fazladan 3 kez daha Hasar ver."
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Rastgele olarak [Arg3] kez <Damage:[Damage:Arg1]> <PunctureDamagewords:Delici Hasar> ver. Her isabet şu etkiyi uygular: Hedefin <ExhaustionIconKeywords:GÜÇ> değerini geçici olarak [Exhaustion:Arg2] azalt; [Power:Arg2] <PowerIconKeywords:Geçici GÜÇ> kazan. Elde, üzerinde <DepleteIconKeywords:Tüketme>, <HuihuanaKeywords:Rondino> ya da <XushiAKeywords:Yükselen Ezgi> bulunmayan 1 Türetilmemiş Komut Kartı seç ve ona \"<HuihuanbKeywords:Rondino>\" ekle. Eğer elinde bu koşulları sağlayan hiçbir kart yoksa, bunun yerine fazladan 3 kez daha Hasar ver."
  },
  Skill_59477_Desc_0 = {
    Text = "Rastgele 3 kez <Damage:[Damage:Arg1]> puan <PunctureDamagewords:Delici Hasar> ver, her hasar verişte hedeften [Arg2] puan <PowerIconKeywords:Güç> <TouquKeywords:Çal>. Eldeki \"Melodi\" özelliği taşımayan, Tükenmez ve Türetilmemiş 1 Komut Kartına \"<HuihuanaKeywords:Rondino>\" ekle. Her seferinde eklenecek El kartı yoksa bunun yerine 3 kez ek hasar ver."
  },
  Skill_59477_Desc_2 = {
    Text = "Rastgele 3 kez <Damage:[Damage:Arg1]> puan <PunctureDamagewords:Delici Hasar> ver, her hasar verişte hedeften [Arg2] puan <PowerIconKeywords:Güç> <TouquKeywords:Çal>. Eldeki \"Melodi\" özelliği taşımayan, Tükenmez ve Türetilmemiş 1 Komut Kartına \"<HuihuanbKeywords:Rondino>\" ekle. Her seferinde eklenecek El kartı yoksa bunun yerine 3 kez ek hasar ver."
  },
