  Skill_61122_BattleDesc = {
    Text = "\"Darbe\" olarak sayılır. 5x Güç bonusundan yararlanan <Damage:[Damage:Arg1]> Hasar ver ve hedefin %30 <BleedingIconKeywords:Kan Akıtma>'sını tetikle. Kaybedilen HP'nin [Arg3]%'i kadar iyileştirir (<Heal:[Arg2]>). Oynandıktan sonra \"<DerivativeCardKeywords_65:Kızıl Zincirler>\"e dönüşür."
  },
  Skill_61122_Desc = {
    Text = "\"Vuruş\" olarak kabul edilir. <Damage:[Damage:Arg1]> Hasar ver, bu Hasar 5x STR bonusundan yararlanır ve hedefin %30 <BleedingIconKeywords:Kan Akıtma>sını tetikler, kaybedilen HP'nin %15'ini geri kazandırır. Oynandıktan sonra \"<DerivativeCardKeywords_65:Kızıl Zincirler>\"e dönüşür."
