  },
  Skill_61123_Desc_0 = {
    Text = "Helot-catena <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: Ele bir \"<DerivativeCardKeywords_65:Kızıl Zincirler>\" koy ve Helot-catena'nın Komut Kartları \"<RetainIconKeywords:Sakla>\" kazanır. Tur başında, Helot-catena'nın Temel Hasarı bu savaş için +%[Arg2]."
  },
  Skill_61123_Desc_15 = {
    Text = "Helot-catena <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Ele bir \"<DerivativeCardKeywords_65:Kızıl Zincirler>\" yerleştir ve Helot-catena'nın Komut Kartları \"<RetainIconKeywords:Sakla>\" kazanır. Tur başında, bu savaş için Helot-catena'nın Temel HSR +[Arg2]%. Taşkınlık \"Kanlı Zincirler\" serbest bırakıldıktan sonra, eldeki her benzersiz \"Helot-catena\" Komut Kartına 35 yığın <TempPowerKeywords:Geçici Güçlendirme> ver."
