  Skill_66349_AwakerSkillBackgroundStory = {
    Text = "Geçmişi, şimdiyi ve geleceği bilir.\nHer şeyin nasıl var olduğunu ve nasıl yok olacağını bilir.\nO'nun nefesi kulaklarında yankılanır."
  },
  Skill_66349_Desc_0 = {
    Text = "Elde iken, Çekme Desteğinin en üstündeki kart bir Komut Kartı ise, onun bir kopyası ol. Oynandıktan sonra eski hâline dön ve <Energy:[Energy:Arg1]> Aliemus elde et."
  },
  Skill_66349_Desc_1 = {
    Text = "Elde iken, Çekme Desteğinin en üstündeki kart bir Komut Kartıysa, Arithmetica Maliyeti 1 azaltılmış kopyasına dönüş. Oynandıktan sonra eski haline dön ve <Energy:[Energy:Arg1]> Aliemus kazan."
  },
  Skill_66349_EffectNameList = {Text = "Aliemus"},
  Skill_66349_Name = {
    Text = "Her Şeyi Bilen Hakikat"
  },
  Skill_66350_AwakerSkillBackgroundStory = {
    Text = "Gümüş Anahtar'ın kapısının ötesinde, insanlar O'nun Tahtı önünde eğilir, nihai cevapları arar.\nAma o kapının bekçisidir; caydırmak, hatırlatmak ve uyarmakla yükümlüdür.\nBildirmemek onun merhametidir."
  },
  Skill_66350_BattleDesc_0 = {
    Text = "Tawil, <Energy:[Energy:Arg1]> Aliemus kazanır. Ele 1 \"<DerivativeCardKeywords_67:Gümüş Anahtar Şafağı>\" yerleştir. Tawil Arithmetica tükettiğinde, kazanılan S-Enerjisi +%50 artar."
  },
  Skill_66350_BattleDesc_15 = {
    Text = "Tawil, <Energy:[Energy:Arg1]> Aliemus kazanır. Ele 1 \"<DerivativeCardKeywords_67:Gümüş Anahtar Şafağı>\" yerleştir. Tawil Arithmetica tükettiğinde, kazanılan S-Enerjisi %50 artar. Tawil Taşkınlık serbest bıraktıktan sonra, bu turdaki tüm Uyandırıcıların Komut Kartları [Arg2]% Final Hasar bonusu kazanır ve başka bir Uyandırıcı tarafından oynanan bir sonraki Komut Kartı bir kez daha tetiklenir."
  },
  Skill_66350_Desc_0 = {
    Text = "Tawil, <Energy:[Energy:Arg1]> Aliemus kazanır. Ele 1 \"<DerivativeCardKeywords_67:Gümüş Anahtar Şafağı>\" yerleştir. Tawil Arithmetica tükettiğinde, kazanılan S-Enerjisi +%50 artar."
