  Skill_70014_Desc = {
    Text = "10 \"Uçurum Enerjisi\" tüketerek eline 1 adet <DerivativeCardKeywords_60:\"Kraliyet\"> yerleştir; tüm Uyananların Kritik Oranı ve Krit. Hasarı %25 artar."
