  Skill_70286_Desc_1 = {
    Text = "<PVPWeaponKeywords:Kader Çarkı>: Tur sonunda, elindeki Kuşananın \"Beceri\" kartlarının Hasarını, İyileştirmesini ve Karakter Kalkanını [Arg1]% artır."
  },
  Skill_70286_Name_1 = {
    Text = "Mavi Taş Tahtı"
  },
  Skill_70299_AwakerSkillBackgroundStory = {
    Text = "Hayatı boyunca aradığı varış noktası şimdi bekliyor, vaatler fısıldayan kapkaranlık bir kapı.\nAçmadan önce 372 olası gerçeklik hayal etti.\nSonra yalnızca 373'üncüsü kaldı, en çok korktuğu.\nBaşka seçenek yok. Düşüyor.\nNe korkunç bir şanssızlık... onun için ve tüm dünya için."
  },
  Skill_70299_BattleDesc = {
    Text = "Diğer Uyandırıcılar <Energy:[Energy:Arg1]> Aliemus kazanır, tüm düşmanlara [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"yığın\" plural=\"yığın\"> <IntoxicationIconKeywords:Zehir> uygular ve takımın Hasar Güçlendirmesini geçici olarak [Arg3]% artırır."
  },
  Skill_70299_Desc = {
    Text = "Diğer Uyandırıcılar <Energy:[Energy:Arg1]> Aliemus kazanır, tüm düşmanlara [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"yığın\" plural=\"yığın\"> <IntoxicationIconKeywords:Zehir> uygular ve takımın Hasar Güçlendirmesini geçici olarak [Arg3]% artırır. \"Final Formu\": 3 ek kart çek, 3 Arithmetica kazan, tüm düşmanlardaki <IntoxicationIconKeywords:Zehir>'in %50'sini tetikle ve \"Doll: Cehennem\"in Temel Aliemus'unu en fazla 3 kez 50 artır."
  },
  Skill_70299_EffectNameList = {
    Text = "Aliemus,Zehir,Hasar Güçlendirme"
  },
  Skill_70299_Name = {
    Text = "Hakikat ve Uçurum Terminali"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Diğer Uyandırıcılar <Energy:[Energy:Arg4]> Aliemus kazanır, tüm düşmanlara [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"yığın\" plural=\"yığın\"> <IntoxicationIconKeywords:Zehir> uygular, takımın Hasar Güçlendirmesini geçici olarak [Arg3]% artırır ve tüm Uyandırıcıların <IntoxicationIconKeywords:Zehir>, <RetaliateIconKeywords:Karşı Atak> ve Temel HSR'sini %10 artırır. Patron Savaşlarında ek bir \"Final\" yığını kazan."
  },
  Skill_70299_PropertyNameList = {
    Text = "$GrowValue1,SLD*GrowValue2,$GrowValue3%"
  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "Kızıl kapsül mekanik kabuğunun altında şişerken pirinç rezonatör uğuldar, bir petek savunma ağı örer.\nMisel darbeleri havayı yarar; asit sisi ete uyarılar kazır. Hafıza-kesen ışınlar kızgın parlar—sınırı geç, ve seğiren kalıntıların bir petri kabında son bulur."
  },
  Skill_70300_BattleDesc = {
    Text = "<Block:[Block:Arg1]> Karakter Kalkanı kazan. <Energy:[Energy:Arg2]> Aliemus kazan."
  },
  Skill_70300_Desc = {
    Text = "<Block:[Block:Arg1]> Kalkan elde et. \"Doll: Cehennem\" <Energy:[Energy:Arg2]> Aliemus elde eder."
  },
  Skill_70300_EffectNameList = {
    Text = "Karakter Kalkanı,Aliemus"
  },
  Skill_70300_Name = {Text = "Savunma"},
  Skill_70300_PropertyNameList = {
    Text = "Savunma*GrowValue1,$GrowValue2"
  },
  Skill_70301_AwakerSkillBackgroundStory = {
    Text = "Kıskaçlar geçmişinin, soy çizgisinin kalıntılarıdır. Asla vazgeçmediği bir güç.\nBir düşmanın göğsüne saplandığında, gülümsemesi bir yara gibi açılır... bu ne anlama gelir? Bunu yalnızca ölüler söyleyebilir, ama onlar konuşmaz."
  },
  Skill_70301_BattleDesc = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver. <Energy:[Energy:Arg2]> Aliemus kazan."
  },
  Skill_70301_Desc = {
    Text = "<Damage:[Damage:Arg1]> Hasar ver. \"Doll: Cehennem\" <Energy:[Energy:Arg2]> Aliemus elde eder."
  },
  Skill_70301_EffectNameList = {
    Text = "HASAR,Aliemus"
  },
  Skill_70301_Name = {Text = "Darbe"},
  Skill_70301_PropertyNameList = {
    Text = "Saldırı*GrowValue1,$GrowValue2"
  },
  Skill_70302_AwakerSkillBackgroundStory = {
    Text = "Kendini feda etti, gizli gerçeğe giden yolu satın aldı. \nElini geri çektiğinde, ruhu erimiş balmumu gibi damlıyordu."
  },
  Skill_70302_BattleDesc_0 = {
    Text = "\"Doll: Cehennem\" <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Tur sonunda <Heal:[Heal:Arg2]> Can yeniler ve <Energy:[Energy:Arg4]> Aliemus kazanır. \"Final Formu\": Artık Can yenilemez; bunun yerine tüm düşmanlara [Arg3]% <IntoxicationIconKeywords:Zehir> tetikler."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "\"Doll: Cehennem\" <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Her \"Final\" yığını başına, Hasar Güçlendirmesi +%8. \"Yanılsamanın Sonu\" tüm Uyandırıcılara %30 Temel Aliemus verir. Tur sonunda, <Heal:[Heal:Arg2]> Can yenilenir ve <Energy:[Energy:Arg4]> Aliemus kazanılır. \"Final Formu\": Artık Can yenilenmez, bunun yerine tüm düşmanlara %[Arg3] <IntoxicationIconKeywords:Zehir> tetiklenir."
  },
  Skill_70302_Desc_0 = {
    Text = "\"Doll: Cehennem\" <Energy:[Energy:Arg1]> puan Delilik kazanır. <ExaltIconKeywords:Gnosis Uyanış>: Tur sonunda <Heal:[Heal:Arg2]> puan Can yeniler ve kendi Delilik yenilenmesine eşit Delilik kazanır. \"Son Form\": Artık Can yenilemez, bunun yerine tüm düşmanlara [Arg3]% <IntoxicationIconKeywords:Zehir> tetikler."
  },
  Skill_70302_Desc_15 = {
    Text = "\"Doll: Cehennem\" <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Her \"Final\" yığını başına Hasar Güçlendirmesi +%8. \"Yanılsamanın Sonu\" tüm Uyandırıcılara %30 Temel Aliemus verir. Tur sonunda <Heal:[Heal:Arg2]> Can yeniler ve Aliemus Yenilenmesine eşit Aliemus kazanır. \"Final Formu\": Artık Can yenilemez, bunun yerine tüm düşmanlara [Arg3]% <IntoxicationIconKeywords:Zehir> tetikler."
  },
  Skill_70302_EffectNameList = {
    Text = "Aliemus,İyileştirme,Zehir Tetiklenme%"
  },
  Skill_70302_Name = {
    Text = "Ruh Çürümesi"
  },
  Skill_70302_PropertyNameList = {
    Text = "$GrowValue1,KON*GrowValue2,$GrowValue3%,"
  },
  Skill_70303_AwakerSkillBackgroundStory = {
    Text = "İnsanlık zaten yok oluşa giden tek yönlü bir yoldaysa, onlara küçük bir itme vermek bir merhamet eylemi midir?\nBırakın son bir anda gelsin. Bırakın acı kristalleşsin. Bırakın âşıklar unutuş onları alırken birbirlerine sarılsın. \nFinalde hiçbir şey acıtmıyorsa, bu sonunda cennet olabilir mi?"
  },
  Skill_70303_BattleDesc_0 = {
    Text = "Tüm düşmanlara Maksimum Can'larının %30'u kadar <RealDamage:Sabit Hasar> ver (minimum [Arg2]). Kullanımdan sonra, \"Doll: Cehennem\"in özel becerileri \"Final Formu\"na geçer."
  },
  Skill_70303_BattleDesc_3 = {
    Text = "Tüm düşmanlara Maksimum Can'larının %30'u kadar <RealDamage:Sabit Hasar> ver (minimum [Arg2]), kaybedilen Can'ın %30'unu geri yükler (<Heal:[Heal:Arg3]>). Kullanımdan sonra, \"Doll: Cehennem\"in özel becerileri \"Final Formu\"na geçer."
  },
  Skill_70303_Desc_0 = {
    Text = "Her düşmanın Maksimum Can'ının %25'i kadar <RealDamage:Sabit Hasar> ver; minimum hasar kendi Maksimum Can'ının [Arg1]%'sine eşittir. Kullanımdan sonra, \"Doll: Cehennem\"in özel becerileri \"Final Formu\"na geçer. \"Yanılsamanın Sonu\" etkisi yalnızca bir kez etkinleşir."
  },
  Skill_70303_Desc_3 = {
    Text = "Tüm düşmanların Maksimum Can'ının %30'u kadar <RealDamage:Sabit Hasar> ver. Bu hasar, kendi Maksimum Can'ının [Arg1]%'sinden az olmaz. Kaybedilen Can'ın %30'unu geri yükler. Kullanımdan sonra, \"Doll: Cehennem\"in özel becerileri \"Final Formu\"na geçer. \"Yanılsamanın Sonu\" etkisi yalnızca bir kez etkinleşir."
  },
  Skill_70303_Name = {
    Text = "Yanılsamanın Sonu"
  },
  Skill_70303_tempBattleDesc_1 = {
    Text = "Tüm düşmanlara Maksimum Can'larının %30'u kadar <RealDamage:Sabit Hasar> ver (minimum [Arg2]). Kullanımdan sonra, \"Doll: Cehennem\"in özel becerileri \"Final Formu\"na geçer."
  },
  Skill_70303_tempBattleDesc_2 = {
    Text = "Tüm düşmanlara Maksimum Can'larının %30'u kadar <RealDamage:Sabit Hasar> ver (minimum [Arg2]), kaybedilen Can'ın %30'unu geri yükler (<Heal:[Heal:Arg3]>). Kullanımdan sonra, \"Doll: Cehennem\"in özel becerileri \"Final Formu\"na geçer."
  },
  Skill_70303_tempBattleDesc_3 = {
    Text = "Tüm düşmanlara Maksimum Can'larının %30'u kadar <FixedDamage:Saf Hasar> ver (minimum [Arg2]). Kaybedilen Can'ın %30'unu geri yükle (<Heal:[Heal:Arg3]>). Kullanımdan sonra, \"Doll: Cehennem\"in özel becerisi \"Final Formu\"na geçer. Tüm Uyandırıcılar %30 Temel Aliemus Üssü kazanır."
  },
  Skill_70304_AwakerSkillBackgroundStory = {
    Text = "Doll'un elleri acımasız bir hassasiyetle çalışır, her ruhun özü onun elinde bir Rubik Küpü kadar uysal. \nBu nazik dahi ücretsiz modifikasyonlar sunar—yan etkileri görmezden gelirseniz oldukça cömert."
  },
