  Skill_78784_Desc = {
    Text = "\"Ortak Duyum\"un her 1 yığını kaldırıldığında, tüm düşmanlara 1 yığın \"Fobik Takıntı\" uygula. Her bir \"Fobik Takıntı\" yığını, verilen Hasarı %3 azaltır."
  },
  Skill_78784_Name = {
    Text = "Dönüşüm: Fobik Takıntı"
  },
  Skill_78785_AwakerSkillBackgroundStory = {
    Text = "\"Lütfen söyleyin bana, gerçek siz kimsiniz?\"\nGülümseyerek sordu.\nZavallı hasta doğal olarak cevap veremezdi, çünkü hafızası değiştirilmişti ve ne kadar peşinden giderse, hafızasına yerleştirilen korkunç varlığa o kadar yaklaşacaktı—ta ki bilinci tamamen çökene ve bir canavara dönüşene kadar."
  },
  Skill_78785_BattleDesc_0 = {
    Text = "Tüm <AnalysisKeywords0:Simbiyoz> yığınlarınızı kaldırın, ardından tüm düşmanlara [Arg6] <plural value=\"[Arg6]\" singular=\"kez\" plural=\"kez\"> <D13AFKeyWord2:Psişik Travma> veya <D13AFKeyWord1:Fobik Takıntı> olarak dönüştürün. Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar verin ve <Posse:[Arg3]> Keyflare kazanın."
  },
  Skill_78785_BattleDesc_2 = {
    Text = "Tüm <AnalysisKeywords0:Simbiyoz> yığınlarınızı kaldırın, ardından tüm düşmanlara <D13AFKeyWord2:Psişik Travma> veya <D13AFKeyWord1:Fobik Takıntı> olarak dönüştürün; kaldırılan her yığın için Clementine'in Temel Hasarını %3 artırır. Tüm düşmanlara [Arg6] <plural value=\"[Arg6]\" singular=\"kez\" plural=\"kez\"> <Damage:[Damage:Arg1]> Hasar verin ve <Posse:[Arg3]> Keyflare kazanın."
  },
  Skill_78785_BattleDesc_3 = {
    Text = "Tüm <AnalysisKeywords3:Simbiyoz> yığınlarını kaldır, ardından tüm düşmanlar üzerinde <D13AFKeyWordQ2:Psişik Travma> veya <D13AFKeyWordQ1:Fobik Takıntı> olarak dönüştür, kaldırılan her yığın için Clementine'in Temel Hasarını %3 artır. Tüm düşmanlara [Arg6] <plural value=\"[Arg6]\" singular=\"kez\" plural=\"kez\"> <Damage:[Damage:Arg1]> Hasar ver ve <Posse:[Arg3]> Keyflare kazan."
  },
  Skill_78785_Desc_0 = {
    Text = "Tüm <AnalysisKeywords0:Ortak Duyum>larını kaldır, ardından tüm düşmanlarda ya <D13AFKeyWord2:Psişik Travma>ya ya da <D13AFKeyWord1:Fobik Takıntı>ya dönüş. Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver. Clementine’in Keyflare Yenilenmesinin [Arg2]%’üne eşit Keyflare kazan."
  },
  Skill_78785_Desc_2 = {
    Text = "Kendinden tüm <AnalysisKeywords3:Ortak Duyum> etkilerini kaldır ve bunları tüm düşmanlar için <D13AFKeyWordQ2:Psişik Travma> ya da <D13AFKeyWordQ1:Fobik Takıntı>ya dönüştürmeyi seç; kaldırılan her yığın için Clementine'in Temel Hasarını %3 artır. Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver. Clementine'in Keyflare Yenilenmesinin [Arg2]%’üne eşit Keyflare kazan."
  },
  Skill_78785_Desc_3 = {
    Text = "Kendinden tüm <AnalysisKeywords3:Ortak Duyum> etkilerini kaldır ve bunları tüm düşmanlar için <D13AFKeyWordQ2:Psişik Travma> ya da <D13AFKeyWordQ1:Fobik Takıntı>ya dönüştürmeyi seç; kaldırılan her yığın için Clementine'in Temel Hasarını %3 artır. Tüm düşmanlara <Damage:[Damage:Arg1]> Hasar ver. Clementine'in Keyflare Yenilenmesinin [Arg2]%’üne eşit Keyflare kazan."
  },
