    Text = "Yaşam Formu Yeniden Yapılandırması"
  },
  Skill_78785_OverLimitUtlSkillDesc_0 = {
    Text = "Tüm <AnalysisKeywords3:Simbiyoz>'u kaldır ve tüm düşmanların <D13AFKeyWordQ2:Psişik Travma>'sına ve <D13AFKeyWordQ1:Fobik Saplantı>'sına dönüştürmeyi seç. <Posse:[Arg4]> puan S-Enerjisi ve [Power:Arg5] puan <PowerIconKeywords:Güç> kazan, tüm düşmanlara <Damage:[Damage:Arg1]> puan hasar [Arg6] kez ver."
  },
  Skill_78785_OverLimitUtlSkillDesc_2 = {
    Text = "Kendinizden tüm <AnalysisKeywords3:Simbiyoz> yığınlarını kaldırın, ardından tüm düşmanlara <D13AFKeyWordQ2:Psişik Travma> ve <D13AFKeyWordQ1:Fobik Takıntı> olarak dönüştürün; kaldırılan her yığın için Clementine'in Temel Hasarını %3 artırır. <Posse:[Arg4]> Keyflare ve [Power:Arg5] <PowerIconKeywords:GÜÇ> elde edin, tüm düşmanlara [Arg6] <plural value=\"[Arg6]\" singular=\"kez\" plural=\"kez\"> <Damage:[Damage:Arg1]> Hasar verin."
  },
  Skill_78785_OverLimitUtlSkillDesc_3 = {
