  Skill_83574_BattleDesc = {
    Text = "Tüm \"Yelken Aç\" yığınlarını temizler ([Arg1]). Temizlenen her yığın için Final Hasar +[Arg2]% artar ve tüm Uyandırıcılar [Arg3] Aliemus kazanır.\nAynı anda 5 veya daha fazla \"Yelken Aç\" yığını temizlenirse, tüm düşmanlara 1 tur boyunca <VulnerabilityIconKeywords:Savunmasız> uygular ve kaybedilen HP'lerinin [Arg4]%'i kadar <RealDamage:Sabit Hasar> verir."
  },
  Skill_83574_Desc = {
    Text = "Tüm \"Yelken Aç\" yığınlarını temizler. Temizlenen her yığın için Final Hasar +%10 artar ve tüm Uyandırıcılar 5 Aliemus kazanır.\n5 veya daha fazla \"Yelken Aç\" yığını aynı anda temizlenirse, tüm düşmanlara 1 tur boyunca \"Savunmasız\" uygular ve kaybedilen HP'lerinin %35'i kadar <RealDamage:Sabit Hasar> verir."
  },
  Skill_83574_Name = {Text = "Demir Alma"},
  Skill_83575_BattleDesc = {
    Text = "Tüm \"Demir Atma\"yı temizle ([Arg1]). Temizlenen her yığın için Ölüm Direnci +[Arg2]%, [Arg3] Arithmetica elde et ve [Arg4] kart çek.\nAynı anda 5 veya daha fazla \"Demir Atma\" yığını temizlenirse, [Arg5] yığın Geçici <ParcloseIconKeywords:Barrier> elde et."
  },
  Skill_83575_Desc = {
    Text = "Tüm \"Demir Atma\" yığınlarını temizle. Temizlenen her yığın için \"Direnç\" +%15, 1 Arithmetica kazan, 1 kart çek.\nAynı anda 5 veya daha fazla \"Demir Atma\" yığını temizlenirse, 1 yığın \"Bariyer\" kazan."
