  Skill_83779_AwakerSkillBackgroundStory = {
    Text = "Sınırsız tuzlu su onu yuttu, ama aynı zamanda ona sığınak oldu.\nO boğucu batış hissinde, derin okyanusu algıladı, derin okyanusla bütünleşti.\nBir gün, deniz tamamen sakinleşecek ve yüzeyinde seyreden her gemiye huzur bahşedilecek.\nO günü bekliyor, Tanrı'nın Diyarı'nın indiği günü."
  },
  Skill_83779_Desc_0 = {
    Text = "Corposant <Energy:[Energy:Arg1]> Aliemus elde eder. <ExaltIconKeywords:Uyanış>: 1 Dokunaç kazan, ele 2 \"<DerivativeCardKeywords_106:Kılavuz>\" kartı ekle. \"Sakin Deniz\" duruşuna geçtikten sonra <Block:[Block:Arg2]> Kalkan kazan, 3 tur bekleme süresiyle."
  },
  Skill_83779_Desc_15 = {
    Text = "Corposant <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: 1 Dokunaç kazan, ele 2 \"<DerivativeCardKeywords_106:Kılavuz>\" ekle. Corposant'ın her tur oynadığı ilk \"Yıldırım Cezası\" ve \"Uğursuz Semafor\" için ele 1 ek \"Kılavuz\" yerleştir. \"<DerivativeCardKeywords_106:Kılavuz>\" etkisi +%50. \"Sakin Deniz\" duruşuna geçtikten sonra <Block:[Block:Arg2]> Kalkan kazan, 3 tur bekleme süresiyle."
  },
  Skill_83779_EffectNameList = {
    Text = "Aliemus,Karakter Kalkanı"
