  Skill_89776_AwakerSkillBackgroundStory = {
    Text = "\"Kardeşim, kanatlarımızı kullanıp uçmaya devam edersek ne kadar yükseğe çıkabiliriz? Bulutların üstüne uçup aya ve yıldızlara dokunabilir miyiz?\"\n\"Belki... yapabiliriz. O zaman çok büyük, güçlü bir çift kanada ihtiyacımız olacak.\"\nEl yazmasındaki derin ve rüya gibi galaksi ve takımyıldızlar çocukların düşlerine yansıyarak kalplerinde gömülü bir dilek tohumu olur."
  },
  Skill_89776_Desc_0 = {
    Text = "Castor <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Castor'un Hasarı her zaman kritik vurur; \"<DerivativeCardKeywords_107:Oniks Tüy>\" oynadıktan sonra hedefe [Corrosion:Arg2] yığın <Corrosion:Aşınma> uygular. Tur sonunda elde Oniks Tüy kartlarını tutmaktan +%50 Kalkan kazanır."
  },
  Skill_89776_Desc_15 = {
    Text = "Castor <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: Castor'un Hasarı her zaman kritik vurur; \"<DerivativeCardKeywords_107:Oniks Tüy>\" oynadıktan sonra hedefe [Corrosion:Arg2] yığın <Corrosion:Aşınma> uygula. Tur sonlarında Oniks Tüy kartlarını elde tutmaktan +50% Kalkan kazan. Her turda ilk kez \"Oniks Tüy\" oynandığında, tüm düşmanlara Yetenek \"Arındırıcı Tüyler\"e eşit Aşınma uygula ve Aşınma kaldırıldığında kaybedilen Can %300'den %500'e çıkar."
  },
