  Skill_95811_Desc_0 = {
    Text = "Doresain <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: [Power:Arg2] <PowerIconKeywords:STR> kazan ve Doresain'in verdiği hasar ek [Arg3]% STR bonusu kazanır. Her turda Doresain'in ilk Öldürme işleminde, taşan hasarın %50'si kadar <RealDamage:Sabit Hasar> diğer düşmanlara verilir."
  },
  Skill_95811_Desc_15 = {
    Text = "Doresain <Energy:[Energy:Arg1]> Aliemus kazanır. <ExaltIconKeywords:Uyanış>: [Power:Arg2] <PowerIconKeywords:STR> kazan. Doresain'in verdiği hasar ek [Arg3]% STR Bonusu kazanır. Tüm düşmanlara mevcut Canın [Arg4]%'si kadar Sabit Hasar ver. Her turda Doresain'in ilk öldürmesinin ardından, diğer düşmanlara taşan hasarın %100'ü kadar <RealDamage:Sabit Hasar> ver."
