  Skill_95819_BattleDesc = {
    Text = "Tüm \"Tokluk\" yığınları temizlenir, eldeki tüm kartlar atılır. <DerivativeCardKeywords_111:\"Ruh Yutma\"> ile kaldırılan kartlar ele yerleştirilir, Arithmetica Maliyetleri 0 olarak ayarlanır. Tur sonunda elde bulunuyorsa: Kaldırılmış kartlardan rastgele 1 tanesinin kopyası ele yerleştirilir, Arithmetica Maliyeti 0 olarak ayarlanır, Tüketim ve Yanılsama eklenir."
  },
  Skill_95819_Desc = {
    Text = "Tüm \"Tokluk\" yığınları temizlenir, eldeki tüm kartlar atılır. <DerivativeCardKeywords_111:\"Ruh Yutma\"> ile kaldırılan kartlar ele yerleştirilir, Arithmetica Maliyetleri 0 olarak ayarlanır. Tur sonunda elde bulunuyorsa: Kaldırılmış kartlardan rastgele 1 tanesinin kopyası ele yerleştirilir, Arithmetica Maliyeti 0 olarak ayarlanır, Tüketim ve Yanılsama eklenir."
