  Skill_95820_AwakerSkillBackgroundStory = {
    Text = "Kılık değiştirmeni yırt. Önyargılarını bırak. Dans pistine çık ve uzun süredir uykuda olan partnerini kucakla.\nNe zamandır ayın gümüş öpücüğünü görmedi? Ne zamandır unutulmuş, şefkatli şeylerin fısıltısını duymadı?\nDinle. O seni arzuluyor, tıpkı senin onu arzuladığın gibi.\nIsır. Yut. Bu eşsiz ziyafette, yaşayanlar ve ölüler ortak, doymak bilmez bir haz içinde birbirine dolanır."
  },
  Skill_95820_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Yutma> :<DerivativeCardKeywords_110:>Bu Taşkınlığın Kritik Oranı +[Arg2]%, [Power:Arg1] puan <PowerIconKeywords:Güç> kazan.] Canı en düşük düşmana <Damage:[Damage:Arg3]> puan Hasar ver; [Arg4]% Güç bonusundan yararlanır ve hedef her %1 Can kaybettiğinde bu Taşkınlığın Final Hasarı %3 artar. Şu anda 3 <CarcassKeywords:Enkaz> varsa bunları tüket, <Heal:[Heal:Arg5]> puan Can iyileştir ve bu Taşkınlığın yararlandığı Kritik Hasar bonusunu iki katına çıkar (şu anda [Arg6]/3 <CarcassKeywords:Enkaz> mevcut)."
  },
  Skill_95820_BattleDesc_3 = {
